// Class 11 Physics Unit V: Motion of System of Particles and Rigid Body
// High-Level Reference Book Content & NCERT Solutions (Zero Text Overlap & Enhanced Table Visibility)

export const c11Phy5HtmlOverview = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n\n  <!-- QUICK GLOSSARY & BASIC DEFINITIONS -->\n  <div style=\"background: rgba(171, 71, 188, 0.05); border: 1.5px solid #AB47BC; border-radius: 12px; padding: 16px; margin-bottom: 25px;\">\n    <h2 class=\"text-center\" style=\"color: #AB47BC; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">📖 Quick Glossary & Basic Definitions</h2>\n    <p class=\"text-center\" style=\"color: #AB47BC; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Fundamental Terms & Concepts for Unit V: Motion of System of Particles and Rigid Body</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>1. Centre of Mass (CM):</b>\n        <span style=\"color: #FFFFFF;\">The single point where the whole mass of a body or system is concentrated and where external forces appear to act.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>2. Rigid Body:</b>\n        <span style=\"color: #FFFFFF;\">A body with a perfectly definite and unchanging shape, where distances between all pairs of constituent particles remain constant.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>3. Torque (τ):</b>\n        <span style=\"color: #FFFFFF;\">The turning or rotational effect of a force about a point or axis of rotation: τ = r × F = |r||F| sin θ.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>4. Angular Momentum (L):</b>\n        <span style=\"color: #FFFFFF;\">The moment of linear momentum of a particle about an axis: L = r × p = |r||p| sin θ = I ω.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>5. Moment of Inertia (I):</b>\n        <span style=\"color: #FFFFFF;\">The quantitative measure of rotational inertia of a body about an axis: I = ∑ mᵢ rᵢ² = ∫ r² dm.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>6. Radius of Gyration (k):</b>\n        <span style=\"color: #FFFFFF;\">The perpendicular distance from axis of rotation at which total mass can be concentrated: I = M k² ⇒ k = √(I / M).</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>7. Conservation of Angular Momentum:</b>\n        <span style=\"color: #FFFFFF;\">If net external torque is zero (τ_ext = 0), total angular momentum remains constant: L = I ω = constant.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>8. Couple:</b>\n        <span style=\"color: #FFFFFF;\">A pair of equal, opposite, non-collinear parallel forces acting on a rigid body that produces pure rotational motion.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>9. Mechanical Equilibrium:</b>\n        <span style=\"color: #FFFFFF;\">A state where both net external force (∑ F_ext = 0) and net external torque (∑ τ_ext = 0) are simultaneously zero.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>10. Rotational Kinetic Energy:</b>\n        <span style=\"color: #FFFFFF;\">The kinetic energy possessed by a body due to pure rotation about an axis: E<sub>rot</sub> = 1/2 I ω<sup>2</sup>.</span>\n      </div>\n    </div>\n  </div>\n\n  <!-- SECTION 1: CENTRE OF MASS OF TWO-PARTICLE AND N-PARTICLE SYSTEMS -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 25px;\">1. Centre of Mass of Two-Particle and N-Particle Systems</h2>\n  \n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Centre of Mass (CM)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The mathematical point in space where the entire mass of a physical system can be assumed to be concentrated for describing its overall translational motion under external forces.</p>\n  </div>\n\n  <p>In extended system analysis, treating every constituent particle individually is computationally complex. By introducing the concept of Centre of Mass, Newton's second law for translational motion applies directly to the system as a whole.</p>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Centre of Mass of a Two-Particle System</h3>\n  <p>Consider two particles of masses m<sub>1</sub> and m<sub>2</sub> located at position vectors r<sub>1</sub> and r<sub>2</sub> relative to an origin O:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span></b></div>\n\n  <p>Along a 1D x-axis with m<sub>1</sub> at x<sub>1</sub> and m<sub>2</sub> at x<sub>2</sub>:</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>X<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> x<sub>1</sub> + m<sub>2</sub> x<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span> &nbsp; (If origin at m<sub>1</sub>: X<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>2</sub> d</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span>)</b></div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(ii) Centre of Mass of an N-Particle System</h3>\n  <p>For a system of N particles of masses m<sub>1</sub>, m<sub>2</sub>, ..., m<sub>N</sub> with total mass M = ∑ m<sub>i</sub>:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">∑ m<sub>i</sub> r<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ( m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub> + ... + m<sub>N</sub> r<sub>N</sub> )</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Centre of Mass of 2-Particle & N-Particle System\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"sphereCyan1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"40%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"85%\" stop-color=\"#00838F\"/>\n      <stop offset=\"100%\" stop-color=\"#004D40\"/>\n    </radialGradient>\n    <radialGradient id=\"sphereGold1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFFDE7\"/>\n      <stop offset=\"40%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"85%\" stop-color=\"#F57F17\"/>\n      <stop offset=\"100%\" stop-color=\"#E65100\"/>\n    </radialGradient>\n    <radialGradient id=\"spherePurple1\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#F3E5F5\"/>\n      <stop offset=\"40%\" stop-color=\"#AB47BC\"/>\n      <stop offset=\"85%\" stop-color=\"#6A1B9A\"/>\n      <stop offset=\"100%\" stop-color=\"#4A148C\"/>\n    </radialGradient>\n\n    <filter id=\"glow3D1\" x=\"-20%\" y=\"-20%\" width=\"140%\" height=\"140%\">\n      <feGaussianBlur stdDeviation=\"5\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n\n    <marker id=\"arrowCyan1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"arrowGreen1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"arrowGold1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FFD700\"/>\n    </marker>\n    <marker id=\"arrowPurple1\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#AB47BC\"/>\n    </marker>\n  </defs>\n\n  <!-- 3D Perspective Ground Grid -->\n  <g opacity=\"0.15\" stroke=\"#94A3B8\" stroke-width=\"1\">\n    <line x1=\"80\" y1=\"380\" x2=\"720\" y2=\"380\"/>\n    <line x1=\"120\" y1=\"320\" x2=\"680\" y2=\"320\"/>\n    <line x1=\"160\" y1=\"270\" x2=\"640\" y2=\"270\"/>\n    <line x1=\"80\" y1=\"380\" x2=\"400\" y2=\"210\"/>\n    <line x1=\"240\" y1=\"380\" x2=\"400\" y2=\"210\"/>\n    <line x1=\"400\" y1=\"380\" x2=\"400\" y2=\"210\"/>\n    <line x1=\"560\" y1=\"380\" x2=\"400\" y2=\"210\"/>\n    <line x1=\"720\" y1=\"380\" x2=\"400\" y2=\"210\"/>\n  </g>\n\n  <!-- 3D Axes -->\n  <line x1=\"100\" y1=\"360\" x2=\"730\" y2=\"360\" stroke=\"#00E5FF\" stroke-width=\"2\" marker-end=\"url(#arrowCyan1)\"/>\n  <line x1=\"100\" y1=\"360\" x2=\"100\" y2=\"40\" stroke=\"#76FF03\" stroke-width=\"2\" marker-end=\"url(#arrowGreen1)\"/>\n  <line x1=\"100\" y1=\"360\" x2=\"30\" y2=\"420\" stroke=\"#FFD700\" stroke-width=\"2\" marker-end=\"url(#arrowGold1)\"/>\n\n  <text x=\"740\" y=\"365\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">X</text>\n  <text x=\"95\" y=\"30\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Y</text>\n  <text x=\"15\" y=\"435\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Z</text>\n  <text x=\"75\" y=\"380\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">O (0,0,0)</text>\n\n  <!-- 3D Drop Shadows -->\n  <ellipse cx=\"240\" cy=\"330\" rx=\"20\" ry=\"8\" fill=\"rgba(0,0,0,0.6)\"/>\n  <ellipse cx=\"600\" cy=\"285\" rx=\"30\" ry=\"12\" fill=\"rgba(0,0,0,0.6)\"/>\n  <ellipse cx=\"480\" cy=\"300\" rx=\"14\" ry=\"6\" fill=\"rgba(0,0,0,0.6)\"/>\n\n  <!-- Vertical Projection Dotted Lines -->\n  <line x1=\"240\" y1=\"210\" x2=\"240\" y2=\"330\" stroke=\"#00E5FF\" stroke-dasharray=\"3,3\" stroke-width=\"1.5\"/>\n  <line x1=\"600\" y1=\"120\" x2=\"600\" y2=\"285\" stroke=\"#FFD700\" stroke-dasharray=\"3,3\" stroke-width=\"1.5\"/>\n  <line x1=\"480\" y1=\"150\" x2=\"480\" y2=\"300\" stroke=\"#AB47BC\" stroke-dasharray=\"3,3\" stroke-width=\"1.5\"/>\n\n  <!-- Line connecting 3D spheres -->\n  <line x1=\"240\" y1=\"210\" x2=\"600\" y2=\"120\" stroke=\"#E2E8F0\" stroke-width=\"2.5\" stroke-dasharray=\"6,4\"/>\n\n  <!-- 3D Sphere 1 (m1) -->\n  <circle cx=\"240\" cy=\"210\" r=\"18\" fill=\"url(#sphereCyan1)\" filter=\"url(#glow3D1)\"/>\n  <text x=\"200\" y=\"175\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">m₁ (2 kg)</text>\n\n  <!-- 3D Sphere 2 (m2) -->\n  <circle cx=\"600\" cy=\"120\" r=\"28\" fill=\"url(#sphereGold1)\" filter=\"url(#glow3D1)\"/>\n  <text x=\"580\" y=\"75\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">m₂ (4 kg)</text>\n\n  <!-- 3D Centre of Mass Sphere (CM) -->\n  <circle cx=\"480\" cy=\"150\" r=\"13\" fill=\"url(#spherePurple1)\" filter=\"url(#glow3D1)\"/>\n  <text x=\"450\" y=\"115\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">CM (R_cm)</text>\n\n  <!-- 3D Position Vectors -->\n  <line x1=\"100\" y1=\"360\" x2=\"230\" y2=\"220\" stroke=\"#00E5FF\" stroke-width=\"3\" marker-end=\"url(#arrowCyan1)\"/>\n  <text x=\"145\" y=\"300\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">r₁</text>\n\n  <line x1=\"100\" y1=\"360\" x2=\"588\" y2=\"128\" stroke=\"#FFD700\" stroke-width=\"3\" marker-end=\"url(#arrowGold1)\"/>\n  <text x=\"340\" y=\"250\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">r₂</text>\n\n  <line x1=\"100\" y1=\"360\" x2=\"470\" y2=\"158\" stroke=\"#AB47BC\" stroke-width=\"3.5\" marker-end=\"url(#arrowPurple1)\"/>\n  <text x=\"260\" y=\"230\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">R_cm</text>\n\n  <!-- Formula Panel Card (Well positioned at bottom right, zero overlap) -->\n  <rect x=\"460\" y=\"330\" width=\"320\" height=\"95\" rx=\"10\" fill=\"rgba(171,71,188,0.18)\" stroke=\"#AB47BC\" stroke-width=\"1.8\"/>\n  <text x=\"475\" y=\"360\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">R_cm = (m₁r₁ + m₂r₂) / (m₁ + m₂)</text>\n  <text x=\"475\" y=\"388\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">✓ 3D Position Vector Formula</text>\n  <text x=\"475\" y=\"410\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13\">• CM lies closer to larger mass m₂</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Volumetric vector diagram showing origin O(0,0,0), position vectors r₁, r₂, and Centre of Mass vector R_cm.\n    </div>\n  </div>\n\n  <!-- SECTION 2: MOMENTUM CONSERVATION & CENTRE OF MASS MOTION -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">2. Momentum Conservation & Centre of Mass Motion</h2>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Velocity and Acceleration of Centre of Mass</h3>\n  <p>Differentiating position vector R<sub>cm</sub> with respect to time t:</p>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Velocity of Centre of Mass (V<sub>cm</sub>):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">V<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dR<sub>cm</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">∑ m<sub>i</sub> v<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">P<sub>total</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Acceleration of Centre of Mass (A<sub>cm</sub>):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">A<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dV<sub>cm</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">∑ m<sub>i</sub> a<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> &nbsp; ⇒ &nbsp; M A<sub>cm</sub> = F<sub>ext</sub></code></span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(ii) Conservation of Linear Momentum of CM</h3>\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Conservation of CM Motion):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">Internal forces between particles cancel out in pairs by Newton's Third Law (F<sub>ij</sub> = -F<sub>ji</sub>). Therefore, internal forces cannot alter the motion of the Centre of Mass.</p>\n  </div>\n\n  <p>If zero net external force acts on a system (F<sub>ext</sub> = 0):</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>M A<sub>cm</sub> = 0 &nbsp; ⇒ &nbsp; V<sub>cm</sub> = Constant &nbsp; ⇒ &nbsp; P<sub>total</sub> = M V<sub>cm</sub> = Constant</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Trajectory of Centre of Mass in Mid-Air Projectile Explosion\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"burstGlow2\" cx=\"50%\" cy=\"50%\" r=\"50%\">\n      <stop offset=\"0%\" stop-color=\"#FFFFFF\"/>\n      <stop offset=\"30%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"70%\" stop-color=\"#FF512F\"/>\n      <stop offset=\"100%\" stop-color=\"transparent\"/>\n    </radialGradient>\n    <filter id=\"glowStrong2\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"7\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n  </defs>\n\n  <!-- 3D Perspective Ground Grid -->\n  <polygon points=\"60,390 740,390 660,330 140,330\" fill=\"rgba(148,163,184,0.06)\" stroke=\"#334155\" stroke-width=\"1.5\"/>\n  <line x1=\"60\" y1=\"390\" x2=\"140\" y2=\"330\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <line x1=\"230\" y1=\"390\" x2=\"270\" y2=\"330\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <line x1=\"400\" y1=\"390\" x2=\"400\" y2=\"330\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <line x1=\"570\" y1=\"390\" x2=\"530\" y2=\"330\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <line x1=\"740\" y1=\"390\" x2=\"660\" y2=\"330\" stroke=\"#475569\" stroke-width=\"1\"/>\n  <text x=\"80\" y=\"415\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">3D Ground Plane</text>\n\n  <!-- 3D Shadow of Parabolic Path -->\n  <path d=\"M 100 360 Q 400 340 700 360\" fill=\"none\" stroke=\"rgba(0,0,0,0.6)\" stroke-width=\"6\"/>\n\n  <!-- Uninterrupted Parabolic CM Trajectory in 3D Space -->\n  <path d=\"M 100 360 Q 400 50 700 360\" fill=\"none\" stroke=\"#AB47BC\" stroke-width=\"4\" stroke-dasharray=\"10,6\" filter=\"url(#glowStrong2)\"/>\n  <text x=\"470\" y=\"115\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Uninterrupted Parabolic CM Trajectory</text>\n\n  <!-- Launch Point -->\n  <circle cx=\"100\" cy=\"360\" r=\"10\" fill=\"#00E5FF\" filter=\"url(#glowStrong2)\"/>\n  <text x=\"45\" y=\"350\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Launch</text>\n\n  <!-- Mid-Air Explosion Point (Positioned clearly at apex cy=200) -->\n  <circle cx=\"400\" cy=\"200\" r=\"35\" fill=\"url(#burstGlow2)\"/>\n  <circle cx=\"400\" cy=\"200\" r=\"12\" fill=\"#FFFFFF\" stroke=\"#FF512F\" stroke-width=\"3\"/>\n  <text x=\"290\" y=\"150\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">💥 Internal Explosion (F_ext = Gravity Only)</text>\n\n  <!-- 3D Fragment Trajectories (Well-spaced) -->\n  <path d=\"M 400 200 Q 520 110 620 360\" fill=\"none\" stroke=\"#FF512F\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n  <circle cx=\"620\" cy=\"360\" r=\"9\" fill=\"#FF512F\" filter=\"url(#glowStrong2)\"/>\n  <text x=\"635\" y=\"355\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Fragment m₁</text>\n\n  <path d=\"M 400 200 Q 360 280 330 370\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n  <circle cx=\"330\" cy=\"370\" r=\"7\" fill=\"#00E5FF\" filter=\"url(#glowStrong2)\"/>\n  <text x=\"245\" y=\"380\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Fragment m₂</text>\n\n  <path d=\"M 400 200 Q 570 240 730 350\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n  <circle cx=\"730\" cy=\"350\" r=\"11\" fill=\"#76FF03\" filter=\"url(#glowStrong2)\"/>\n  <text x=\"660\" y=\"380\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13\" font-weight=\"bold\">Fragment m₃</text>\n\n  <!-- Explanation Card Top Left -->\n  <rect x=\"70\" y=\"40\" width=\"320\" height=\"90\" rx=\"10\" fill=\"rgba(15,23,42,0.9)\" stroke=\"#AB47BC\" stroke-width=\"1.8\"/>\n  <text x=\"85\" y=\"68\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Newton's 2nd Law for System:</text>\n  <text x=\"85\" y=\"92\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15\" font-weight=\"bold\">F_ext = M A_cm = M g</text>\n  <text x=\"85\" y=\"115\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Internal forces cancel out (∑ F_int = 0)</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D spatial trajectory diagram demonstrating uninterrupted parabolic path of CM despite internal explosion scattering fragments.\n    </div>\n  </div>\n\n  <!-- SECTION 3: CENTRE OF MASS OF RIGID BODIES & UNIFORM ROD -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">3. Centre of Mass of a Rigid Body & Uniform Rod</h2>\n\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Continuous Mass Distribution CM):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">For a rigid body with continuous distribution of mass dm at position r, summation is replaced by integration over the volume of the body.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ∫ r dm &nbsp;|&nbsp; X<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ∫ x dm &nbsp;|&nbsp; Y<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ∫ y dm</b></div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Derivation for Centre of Mass of a Uniform Rod</h3>\n  <p>Consider a uniform rod of mass M, length L, and linear mass density λ = M / L aligned from x = 0 to x = L:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #AB47BC; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    <div style=\"color: #FFFFFF; font-size: 15.5px; font-weight: bold;\">Mass element dm = λ dx = (M / L) dx</div>\n    <div style=\"color: #FFFFFF; font-size: 16px; font-weight: bold; margin-top: 6px; color: #AB47BC;\">X<sub>cm</sub> = \" + frac('1', 'M') + \" ∫<sub>0</sub><sup>L</sup> x [ (M / L) dx ] = \" + frac('1', 'L') + \" [ x<sup>2</sup> / 2 ]<sub>0</sub><sup>L</sup> = \" + frac('1', 'L') + \" ( \" + frac('L<sup>2</sup>', '2') + \" ) = \" + frac('L', '2') + \"</div>\n  </div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(ii) CM of Symmetric Geometrical Bodies</h3>\n  <div style=\"margin: 10px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Uniform Ring / Disc / Sphere:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">Located at geometric center of symmetry.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Uniform Semi-Circular Ring:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Y<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2 R</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">π</span>\n  </span></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Uniform Semi-Circular Disc:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Y<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">4 R</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3 π</span>\n  </span></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Uniform Solid Hemisphere:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">Y<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">3 R</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">8</span>\n  </span></code></span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Centre of Mass of Uniform Rod and Semi-Circular Ring/Disc\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"rod3DGrad3\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"30%\" stop-color=\"#0284C7\"/>\n      <stop offset=\"70%\" stop-color=\"#0369A1\"/>\n      <stop offset=\"100%\" stop-color=\"#075985\"/>\n    </linearGradient>\n    <radialGradient id=\"ring3DGrad3\" cx=\"50%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"#E1BEE7\"/>\n      <stop offset=\"50%\" stop-color=\"#AB47BC\"/>\n      <stop offset=\"100%\" stop-color=\"#4A148C\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Half: 3D Uniform Rod -->\n  <g transform=\"translate(40, 30)\">\n    <text x=\"90\" y=\"30\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">1. 3D Uniform Rod (Length L)</text>\n\n    <!-- 3D Rod Shadow -->\n    <ellipse cx=\"180\" cy=\"230\" rx=\"140\" ry=\"12\" fill=\"rgba(0,0,0,0.5)\"/>\n\n    <!-- 3D Rod Body -->\n    <rect x=\"40\" y=\"140\" width=\"280\" height=\"38\" rx=\"6\" fill=\"url(#rod3DGrad3)\" stroke=\"#38BDF8\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"320\" cy=\"159\" rx=\"10\" ry=\"19\" fill=\"#0284C7\" stroke=\"#38BDF8\" stroke-width=\"1.5\"/>\n    <ellipse cx=\"40\" cy=\"159\" rx=\"10\" ry=\"19\" fill=\"#38BDF8\" stroke=\"#38BDF8\" stroke-width=\"1.5\"/>\n\n    <!-- Element dm -->\n    <rect x=\"172\" y=\"140\" width=\"16\" height=\"38\" fill=\"#FF512F\"/>\n    <text x=\"155\" y=\"120\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"13.5\" font-weight=\"bold\">dm = λ dx</text>\n\n    <!-- CM Sphere -->\n    <circle cx=\"180\" cy=\"159\" r=\"8\" fill=\"#FFD700\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <line x1=\"180\" y1=\"159\" x2=\"180\" y2=\"255\" stroke=\"#FFD700\" stroke-dasharray=\"4,4\" stroke-width=\"2\"/>\n\n    <!-- Formula Badge -->\n    <rect x=\"110\" y=\"270\" width=\"140\" height=\"42\" rx=\"8\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#FFD700\" stroke-width=\"1.5\"/>\n    <text x=\"125\" y=\"297\" fill=\"#FFD700\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">X_cm = L / 2</text>\n  </g>\n\n  <!-- Vertical Partition -->\n  <line x1=\"400\" y1=\"40\" x2=\"400\" y2=\"410\" stroke=\"#334155\" stroke-width=\"2\" stroke-dasharray=\"6,6\"/>\n\n  <!-- Right Half: 3D Volumetric Semi-Circular Ring & Disc -->\n  <g transform=\"translate(420, 30)\">\n    <text x=\"40\" y=\"30\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">2. 3D Semi-Circular Ring & Disc</text>\n\n    <!-- Base Axes -->\n    <line x1=\"40\" y1=\"280\" x2=\"300\" y2=\"280\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <line x1=\"170\" y1=\"280\" x2=\"170\" y2=\"60\" stroke=\"#475569\" stroke-width=\"2\"/>\n    <text x=\"175\" y=\"75\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">Y</text>\n    <text x=\"175\" y=\"295\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">O</text>\n\n    <!-- 3D Ring Shadow -->\n    <ellipse cx=\"170\" cy=\"290\" rx=\"100\" ry=\"12\" fill=\"rgba(0,0,0,0.5)\"/>\n\n    <!-- 3D Volumetric Semi-Circular Arc -->\n    <path d=\"M 70 280 A 100 100 0 0 1 270 280\" fill=\"none\" stroke=\"url(#ring3DGrad3)\" stroke-width=\"12\" stroke-linecap=\"round\"/>\n\n    <!-- Ring CM Badge (Well spaced at y=175) -->\n    <circle cx=\"170\" cy=\"205\" r=\"7\" fill=\"#00E5FF\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <rect x=\"185\" y=\"175\" width=\"165\" height=\"34\" rx=\"6\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"1.2\"/>\n    <text x=\"195\" y=\"197\" fill=\"#00E5FF\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">Ring: Y_cm = 2R / π</text>\n\n    <!-- Disc CM Badge (Well spaced at y=225) -->\n    <circle cx=\"170\" cy=\"232\" r=\"7\" fill=\"#FFD700\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <rect x=\"185\" y=\"225\" width=\"165\" height=\"34\" rx=\"6\" fill=\"rgba(255,215,0,0.15)\" stroke=\"#FFD700\" stroke-width=\"1.2\"/>\n    <text x=\"195\" y=\"247\" fill=\"#FFD700\" font-family=\"monospace\" font-size=\"14\" font-weight=\"bold\">Disc: Y_cm = 4R / 3π</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Volumetric model demonstrating X_cm = L/2 for rod and Y_cm = 2R/π for semi-circular ring.\n    </div>\n  </div>\n\n  <!-- SECTION 4: TORQUE & ANGULAR MOMENTUM -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">4. Moment of a Force (Torque) & Angular Momentum</h2>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Moment of a Force (Torque τ)</h3>\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Torque (τ)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The rotational analogue of force, defined as the vector cross product of position vector r and applied force F.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>τ = r × F = |r| |F| sin θ n̂ = Force × Perpendicular Distance (F r<sub>⊥</sub>)</b> &nbsp; (SI Unit: <b>N m</b>)</div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(ii) Angular Momentum (L)</h3>\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Angular Momentum (L)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The rotational analogue of linear momentum, defined as the vector cross product of position vector r and linear momentum p.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>L = r × p = |r| |p| sin θ n̂ = I ω</b> &nbsp; (SI Unit: <b>kg m<sup>2</sup> s<sup>-1</sup> or J s</b>)</div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(iii) Relation Between Torque and Angular Momentum</h3>\n  <p>Differentiating angular momentum L = r × p with respect to time t:</p>\n  \n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #AB47BC; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    <div style=\"color: #FFFFFF; font-size: 15.5px; font-weight: bold;\">dL / dt = d(r × p)/dt = (dr/dt × p) + (r × dp/dt)</div>\n    <div style=\"color: #FFFFFF; font-size: 15.5px;\">Since dr/dt = v and p = m v, (v × m v) = 0. And dp/dt = F:</div>\n    <div style=\"color: #FFFFFF; font-size: 16px; font-weight: bold; margin-top: 6px; color: #AB47BC;\">dL / dt = r × F = τ<sub>ext</sub></div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Vector Cross Product Diagram for Torque τ = r × F\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <filter id=\"glowGreen4\" x=\"-30%\" y=\"-30%\" width=\"160%\" height=\"160%\">\n      <feGaussianBlur stdDeviation=\"6\" result=\"blur\"/>\n      <feComposite in=\"SourceGraphic\" in2=\"blur\" operator=\"over\"/>\n    </filter>\n    <marker id=\"arrowGreen3D4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n    <marker id=\"arrowPink3D4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowCyan3D4\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n  </defs>\n\n  <!-- 3D Perspective Base Plane -->\n  <polygon points=\"120,350 420,350 620,250 320,250\" fill=\"rgba(148,163,184,0.08)\" stroke=\"#475569\" stroke-width=\"2\"/>\n  <line x1=\"120\" y1=\"350\" x2=\"620\" y2=\"250\" stroke=\"#334155\" stroke-dasharray=\"4,4\"/>\n  <line x1=\"420\" y1=\"350\" x2=\"320\" y2=\"250\" stroke=\"#334155\" stroke-dasharray=\"4,4\"/>\n\n  <!-- Pivot Point O -->\n  <circle cx=\"320\" cy=\"300\" r=\"9\" fill=\"#FFFFFF\" filter=\"url(#glowGreen4)\"/>\n  <text x=\"280\" y=\"320\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Pivot (O)</text>\n\n  <!-- Position Vector r -->\n  <line x1=\"320\" y1=\"300\" x2=\"520\" y2=\"300\" stroke=\"#00E5FF\" stroke-width=\"4\" marker-end=\"url(#arrowCyan3D4)\"/>\n  <text x=\"400\" y=\"330\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">r (Position Vector)</text>\n\n  <!-- Applied Force F (Tilted in Space, label well clear at x=655) -->\n  <line x1=\"520\" y1=\"300\" x2=\"640\" y2=\"180\" stroke=\"#FF512F\" stroke-width=\"4\" marker-end=\"url(#arrowPink3D4)\"/>\n  <text x=\"655\" y=\"175\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">F (Force)</text>\n\n  <!-- Angle theta Arc -->\n  <path d=\"M 560 300 A 40 40 0 0 0 550 270\" fill=\"none\" stroke=\"#FFD700\" stroke-width=\"2.5\"/>\n  <text x=\"565\" y=\"280\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">θ</text>\n\n  <!-- 3D Torque Vector τ (Vertical UPWARD, label clear at x=345, y=65) -->\n  <line x1=\"320\" y1=\"300\" x2=\"320\" y2=\"60\" stroke=\"#76FF03\" stroke-width=\"5\" marker-end=\"url(#arrowGreen3D4)\" filter=\"url(#glowGreen4)\"/>\n  <text x=\"345\" y=\"65\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"20\" font-weight=\"bold\">τ = r × F (Torque)</text>\n\n  <!-- Right Hand Rule Spiral Curve -->\n  <path d=\"M 360 280 A 40 25 0 0 0 330 255\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\" stroke-dasharray=\"4,4\"/>\n  <text x=\"180\" y=\"170\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"13.5\">Right-Hand Thumb Rule Direction</text>\n\n  <!-- Formula Panel -->\n  <rect x=\"50\" y=\"45\" width=\"240\" height=\"95\" rx=\"10\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.8\"/>\n  <text x=\"65\" y=\"75\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">τ = r × F</text>\n  <text x=\"65\" y=\"100\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"15\">|τ| = r F sin θ</text>\n  <text x=\"65\" y=\"125\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"13\">SI Unit: N m</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D vector spatial plane showing position vector r, applied force F, and vertical torque vector τ = r × F.\n    </div>\n  </div>\n\n  <!-- SECTION 5: CONSERVATION OF ANGULAR MOMENTUM & APPLICATIONS -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">5. Law of Conservation of Angular Momentum & Applications</h2>\n\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Law of Conservation of Angular Momentum):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">If the net external torque acting on a rotating system is zero (τ_ext = 0), the total angular momentum of the system remains strictly constant.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>τ<sub>ext</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dL</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> = 0 &nbsp; ⇒ &nbsp; L = I ω = I<sub>1</sub> ω<sub>1</sub> = I<sub>2</sub> ω<sub>2</sub> = Constant</b></div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Practical Applications</h3>\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Acrobat / Ice Skater Spinning:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">When an ice skater pulls arms and legs inward toward axis of rotation, moment of inertia I decreases. To conserve L = I ω, angular speed ω increases dramatically!</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Diver Jumping from Springboard:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">After leaving springboard, diver folds body (curling arms and legs) to reduce I, causing fast rotational somersaults (high ω). Before touching water, diver stretches body to increase I and slow down rotation for a smooth entry.</span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Planetary Motion (Kepler's Second Law):</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\">As a planet moves closer to Sun in elliptical orbit, radius r decreases, so moment of inertia I = m r<sup>2</sup> decreases. To conserve L, orbital speed v (or ω) increases.</span>\n  </div>\n  </div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Conservation of Angular Momentum Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"weightGrad5\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"100%\" stop-color=\"#B78103\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Side: 3D Platform (Arms Extended) -->\n  <g transform=\"translate(60, 30)\">\n    <text x=\"70\" y=\"30\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Arms Extended (Large I₁)</text>\n\n    <!-- 3D Rotating Platform -->\n    <ellipse cx=\"170\" cy=\"320\" rx=\"110\" ry=\"25\" fill=\"rgba(0,229,255,0.15)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <ellipse cx=\"170\" cy=\"315\" rx=\"110\" ry=\"25\" fill=\"rgba(2,132,199,0.3)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n\n    <!-- Central Axis -->\n    <line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"320\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"6,6\"/>\n\n    <!-- 3D Figure Silhouette -->\n    <circle cx=\"170\" cy=\"90\" r=\"20\" fill=\"#E2E8F0\"/>\n    <line x1=\"170\" y1=\"110\" x2=\"170\" y2=\"240\" stroke=\"#E2E8F0\" stroke-width=\"10\"/>\n\n    <!-- Extended Arms & Dumbbells -->\n    <line x1=\"60\" y1=\"140\" x2=\"280\" y2=\"140\" stroke=\"#FF512F\" stroke-width=\"8\"/>\n    <circle cx=\"60\" cy=\"140\" r=\"14\" fill=\"url(#weightGrad5)\"/>\n    <circle cx=\"280\" cy=\"140\" r=\"14\" fill=\"url(#weightGrad5)\"/>\n\n    <!-- Slow Rotation Arrow -->\n    <path d=\"M 120 70 A 50 20 0 0 1 220 70\" fill=\"none\" stroke=\"#00E5FF\" stroke-width=\"3\"/>\n\n    <text x=\"75\" y=\"285\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Large I₁ &nbsp;|&nbsp; Slow ω₁</text>\n  </g>\n\n  <!-- Central Equality Banner -->\n  <g transform=\"translate(385, 185)\">\n    <rect x=\"-45\" y=\"-22\" width=\"90\" height=\"44\" rx=\"10\" fill=\"rgba(171,71,188,0.25)\" stroke=\"#AB47BC\" stroke-width=\"2\"/>\n    <text x=\"-32\" y=\"6\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">L = Const</text>\n  </g>\n\n  <!-- Right Side: 3D Platform (Arms Retracted) -->\n  <g transform=\"translate(460, 30)\">\n    <text x=\"70\" y=\"30\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">2. Arms Tucked In (Small I₂)</text>\n\n    <!-- 3D Rotating Platform -->\n    <ellipse cx=\"170\" cy=\"320\" rx=\"110\" ry=\"25\" fill=\"rgba(118,255,3,0.15)\" stroke=\"#76FF03\" stroke-width=\"2\"/>\n    <ellipse cx=\"170\" cy=\"315\" rx=\"110\" ry=\"25\" fill=\"rgba(74,222,128,0.3)\" stroke=\"#76FF03\" stroke-width=\"2\"/>\n\n    <!-- Central Axis -->\n    <line x1=\"170\" y1=\"50\" x2=\"170\" y2=\"320\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"6,6\"/>\n\n    <!-- 3D Figure Silhouette -->\n    <circle cx=\"170\" cy=\"90\" r=\"20\" fill=\"#E2E8F0\"/>\n    <line x1=\"170\" y1=\"110\" x2=\"170\" y2=\"240\" stroke=\"#E2E8F0\" stroke-width=\"10\"/>\n\n    <!-- Tucked Arms & Dumbbells -->\n    <line x1=\"135\" y1=\"140\" x2=\"205\" y2=\"140\" stroke=\"#FF512F\" stroke-width=\"8\"/>\n    <circle cx=\"135\" cy=\"140\" r=\"14\" fill=\"url(#weightGrad5)\"/>\n    <circle cx=\"205\" cy=\"140\" r=\"14\" fill=\"url(#weightGrad5)\"/>\n\n    <!-- Fast Spin Multiple Arrows -->\n    <path d=\"M 110 70 A 60 22 0 0 1 230 70\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"4\"/>\n    <path d=\"M 115 60 A 55 18 0 0 1 225 60\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"2.5\"/>\n\n    <text x=\"75\" y=\"285\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">Small I₂ &nbsp;|&nbsp; Fast ω₂</text>\n  </g>\n\n  <!-- Bottom Formula Banner -->\n  <rect x=\"200\" y=\"375\" width=\"400\" height=\"45\" rx=\"10\" fill=\"rgba(0,0,0,0.5)\" stroke=\"#AB47BC\" stroke-width=\"1.8\"/>\n  <text x=\"215\" y=\"403\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16\" font-weight=\"bold\">I₁ ω₁ = I₂ ω₂ &nbsp; ⇒ &nbsp; ω₂ = (I₁ / I₂) ω₁</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Volumetric platform model comparing extended arms (large I₁, slow ω₁) vs tucked arms (small I₂, fast ω₂).\n    </div>\n  </div>\n\n  <!-- SECTION 6: EQUILIBRIUM OF RIGID BODIES & COUPLE -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">6. Equilibrium of Rigid Bodies & Couple</h2>\n\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Complete Mechanical Equilibrium):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A rigid body is in complete mechanical equilibrium if it possesses simultaneous translational equilibrium AND rotational equilibrium.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.25); border-left: 4px solid #AB47BC; border-radius: 8px; padding: 14px; margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Translational Equilibrium:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">∑ F<sub>ext</sub> = 0 &nbsp; ⇒ &nbsp; ∑ F<sub>x</sub> = 0, &nbsp; ∑ F<sub>y</sub> = 0, &nbsp; ∑ F<sub>z</sub> = 0 &nbsp; (A<sub>cm</sub> = 0)</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Rotational Equilibrium:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">∑ τ<sub>ext</sub> = 0 &nbsp; ⇒ &nbsp; ∑ τ<sub>x</sub> = 0, &nbsp; ∑ τ<sub>y</sub> = 0, &nbsp; ∑ τ<sub>z</sub> = 0 &nbsp; (α = 0)</code></span>\n  </div>\n  </div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Couple and Moment of a Couple</h3>\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Couple):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">A pair of two equal, opposite, and non-collinear parallel forces acting on a rigid body at different points.</p>\n  </div>\n\n  <p>A couple produces pure rotational motion without any translational acceleration (since ∑ F = 0 but ∑ τ ≠ 0).</p>\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>Torque of a Couple = Magnitude of Either Force × Perpendicular Distance between Forces (F × d)</b></div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Couple Forces and Pure Rotational Equilibrium\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"bar3D6\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#64748B\"/>\n      <stop offset=\"50%\" stop-color=\"#334155\"/>\n      <stop offset=\"100%\" stop-color=\"#1E293B\"/>\n    </linearGradient>\n    <marker id=\"arrowUp6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#00E5FF\"/>\n    </marker>\n    <marker id=\"arrowDown6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#FF512F\"/>\n    </marker>\n    <marker id=\"arrowGreen3D6\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"4\" orient=\"auto\">\n      <path d=\"M0,0 L8,4 L0,8 Z\" fill=\"#76FF03\"/>\n    </marker>\n  </defs>\n\n  <!-- 3D Bar Shadow -->\n  <ellipse cx=\"400\" cy=\"240\" rx=\"200\" ry=\"16\" fill=\"rgba(0,0,0,0.5)\"/>\n\n  <!-- 3D Metallic Cylindrical Bar -->\n  <rect x=\"200\" y=\"190\" width=\"400\" height=\"34\" rx=\"8\" fill=\"url(#bar3D6)\" stroke=\"#94A3B8\" stroke-width=\"2\"/>\n  <ellipse cx=\"600\" cy=\"207\" rx=\"12\" ry=\"17\" fill=\"#334155\" stroke=\"#94A3B8\" stroke-width=\"1.5\"/>\n  <ellipse cx=\"200\" cy=\"207\" rx=\"12\" ry=\"17\" fill=\"#64748B\" stroke=\"#94A3B8\" stroke-width=\"1.5\"/>\n\n  <!-- Central Pivot Point O -->\n  <circle cx=\"400\" cy=\"207\" r=\"8\" fill=\"#FFD700\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n  <text x=\"395\" y=\"238\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"15\" font-weight=\"bold\">O</text>\n\n  <!-- Force +F at Left End (UPWARD, label at y=45 well clear) -->\n  <line x1=\"240\" y1=\"190\" x2=\"240\" y2=\"60\" stroke=\"#00E5FF\" stroke-width=\"4.5\" marker-end=\"url(#arrowUp6)\"/>\n  <text x=\"185\" y=\"45\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">+F (Upward)</text>\n\n  <!-- Force -F at Right End (DOWNWARD, label at y=375 well clear) -->\n  <line x1=\"560\" y1=\"224\" x2=\"560\" y2=\"340\" stroke=\"#FF512F\" stroke-width=\"4.5\" marker-end=\"url(#arrowDown6)\"/>\n  <text x=\"515\" y=\"375\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"17\" font-weight=\"bold\">-F (Downward)</text>\n\n  <!-- Arm Distance d Dimension -->\n  <line x1=\"240\" y1=\"260\" x2=\"560\" y2=\"260\" stroke=\"#AB47BC\" stroke-width=\"2\"/>\n  <line x1=\"240\" y1=\"250\" x2=\"240\" y2=\"270\" stroke=\"#AB47BC\" stroke-width=\"2\"/>\n  <line x1=\"560\" y1=\"250\" x2=\"560\" y2=\"270\" stroke=\"#AB47BC\" stroke-width=\"2\"/>\n  <text x=\"385\" y=\"282\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"15.5\" font-weight=\"bold\">Arm Distance (d)</text>\n\n  <!-- Clockwise Rotation Arc -->\n  <path d=\"M 360 135 A 65 65 0 0 1 440 135\" fill=\"none\" stroke=\"#76FF03\" stroke-width=\"3.5\" marker-end=\"url(#arrowGreen3D6)\"/>\n  <text x=\"335\" y=\"110\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14.5\" font-weight=\"bold\">Pure Rotation (Clockwise)</text>\n\n  <!-- Bottom Explanatory Panels -->\n  <rect x=\"80\" y=\"310\" width=\"270\" height=\"85\" rx=\"10\" fill=\"rgba(0,229,255,0.1)\" stroke=\"#00E5FF\" stroke-width=\"1.5\"/>\n  <text x=\"95\" y=\"338\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Translational Equilibrium:</text>\n  <text x=\"95\" y=\"365\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15.5\" font-weight=\"bold\">∑ F = F + (-F) = 0</text>\n\n  <rect x=\"450\" y=\"310\" width=\"270\" height=\"85\" rx=\"10\" fill=\"rgba(118,255,3,0.1)\" stroke=\"#76FF03\" stroke-width=\"1.5\"/>\n  <text x=\"465\" y=\"338\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Rotational Couple Torque:</text>\n  <text x=\"465\" y=\"365\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15.5\" font-weight=\"bold\">τ_couple = F × d ≠ 0</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Metallic cylindrical bar model showing equal opposite forces forming couple torque τ = F × d.\n    </div>\n  </div>\n\n  <!-- SECTION 7: RIGID BODY ROTATION & ROTATIONAL KINEMATICS -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">7. Rigid Body Rotation & Equations of Rotational Motion</h2>\n\n  <p>For a rigid body rotating about a fixed axis with constant angular acceleration α:</p>\n\n  <div style=\"margin: 12px 0;\">\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• First Rotational Equation:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">ω = ω<sub>0</sub> + α t</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Second Rotational Equation:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">θ = ω<sub>0</sub> t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> α t<sup>2</sup></code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Third Rotational Equation:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ</code></span>\n  </div>\n    \n  <div style=\"margin-bottom: 12px;\">\n    <b style=\"color: #AB47BC; font-size: 15.5px; display: block; margin-bottom: 3px;\">• Angular Displacement in n-th Second:</b>\n    <span style=\"color: #FFFFFF; line-height: 1.6; display: block; font-size: 15px;\"><code style=\"font-size: 14px; white-space: nowrap; font-family: monospace; color: #FFFFFF; display: inline-block;\">θ<sub>n<sup>th</sup></sub> = ω<sub>0</sub> + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">α</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> (2 n - 1)</code></span>\n  </div>\n  </div>\n\n  <!-- SECTION 8: COMPARISON OF LINEAR AND ROTATIONAL MOTIONS -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">8. Comparison of Linear and Rotational Motions</h2>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Analogous Linear and Rotational Motion Variables Comparison\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 480\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <!-- Header Card (Height 54px, Font 19px) -->\n  <rect x=\"25\" y=\"20\" width=\"750\" height=\"54\" rx=\"12\" fill=\"rgba(171,71,188,0.28)\" stroke=\"#AB47BC\" stroke-width=\"2\"/>\n  <text x=\"135\" y=\"53\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">TRANSLATIONAL MOTION (1D)</text>\n  <text x=\"475\" y=\"53\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"19\" font-weight=\"bold\">ROTATIONAL MOTION (FIXED AXIS)</text>\n\n  <!-- Row 1: Inertia (Cell Height 72px, Font 17.5px) -->\n  <g transform=\"translate(25, 88)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"rgba(0,229,255,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"25\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Mass (Inertia): <tspan fill=\"#00E5FF\" font-weight=\"bold\" font-size=\"20\">m</tspan></text>\n\n    <rect x=\"385\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(118,255,3,0.06)\" stroke=\"rgba(118,255,3,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"405\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Moment of Inertia: <tspan fill=\"#76FF03\" font-weight=\"bold\" font-size=\"20\">I = ∑ m r²</tspan></text>\n  </g>\n\n  <!-- Row 2: Kinematics (Cell Height 72px, Font 17.5px) -->\n  <g transform=\"translate(25, 172)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"rgba(0,229,255,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"25\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Velocity / Accel: <tspan fill=\"#00E5FF\" font-weight=\"bold\" font-size=\"20\">v,  a = dv/dt</tspan></text>\n\n    <rect x=\"385\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(118,255,3,0.06)\" stroke=\"rgba(118,255,3,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"405\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Angular Vel / Accel: <tspan fill=\"#76FF03\" font-weight=\"bold\" font-size=\"20\">ω,  α = dω/dt</tspan></text>\n  </g>\n\n  <!-- Row 3: Force vs Torque (Cell Height 72px, Font 17.5px) -->\n  <g transform=\"translate(25, 256)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"rgba(0,229,255,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"25\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Newton's 2nd Law: <tspan fill=\"#00E5FF\" font-weight=\"bold\" font-size=\"20\">F = m a</tspan></text>\n\n    <rect x=\"385\" y=\"0\" width=\"365\" height=\"72\" rx=\"10\" fill=\"rgba(118,255,3,0.06)\" stroke=\"rgba(118,255,3,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"405\" y=\"43\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"17.5\">Rotational 2nd Law: <tspan fill=\"#76FF03\" font-weight=\"bold\" font-size=\"20\">τ = I α</tspan></text>\n  </g>\n\n  <!-- Row 4: Momentum & Energy (Cell Height 78px, Font 17px) -->\n  <g transform=\"translate(25, 340)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"78\" rx=\"10\" fill=\"rgba(0,229,255,0.06)\" stroke=\"rgba(0,229,255,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"25\" y=\"32\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16.5\">Momentum: <tspan fill=\"#00E5FF\" font-weight=\"bold\" font-size=\"18.5\">p = m v</tspan></text>\n    <text x=\"25\" y=\"60\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16.5\">Kinetic Energy: <tspan fill=\"#00E5FF\" font-weight=\"bold\" font-size=\"18.5\">E_k = ½ m v²</tspan></text>\n\n    <rect x=\"385\" y=\"0\" width=\"365\" height=\"78\" rx=\"10\" fill=\"rgba(118,255,3,0.06)\" stroke=\"rgba(118,255,3,0.3)\" stroke-width=\"1.5\"/>\n    <text x=\"405\" y=\"32\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16.5\">Angular Momentum: <tspan fill=\"#76FF03\" font-weight=\"bold\" font-size=\"18.5\">L = I ω</tspan></text>\n    <text x=\"405\" y=\"60\" fill=\"#FFFFFF\" font-family=\"sans-serif\" font-size=\"16.5\">Rotational K.E.: <tspan fill=\"#76FF03\" font-weight=\"bold\" font-size=\"18.5\">E_rot = ½ I ω²</tspan></text>\n  </g>\n\n  <!-- Bottom Connecting Banner (Font 16px bold) -->\n  <text x=\"200\" y=\"452\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Connecting Bridges: s = r θ  |  v = r ω  |  a_t = r α  |  τ = r × F</text>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 Enhanced 3D Dual-Column Matrix linking translational (m, v, a, F, p, E_k) and rotational (I, ω, α, τ, L, E_rot) variables with enlarged fonts and cell height.\n    </div>\n  </div>\n\n  <!-- SECTION 9: MOMENT OF INERTIA & RADIUS OF GYRATION -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">9. Moment of Inertia & Radius of Gyration</h2>\n\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Moment of Inertia (I)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The property of a rigid body by virtue of which it opposes any change in its state of uniform rotational motion about a specified axis.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>I = ∑ m<sub>i</sub> r<sub>i</sub><sup>2</sup> = m<sub>1</sub> r<sub>1</sub><sup>2</sup> + m<sub>2</sub> r<sub>2</sub><sup>2</sup> + ... + m<sub>N</sub> r<sub>N</sub><sup>2</sup> = ∫ r<sup>2</sup> dm</b> &nbsp; (SI Unit: <b>kg m<sup>2</sup></b>)</div>\n\n  <h3 style=\"color: #AB47BC; margin-top: 20px;\">(i) Radius of Gyration (k)</h3>\n  \n  <div style=\"background: rgba(171, 71, 188, 0.06); border-left: 4px solid #AB47BC; border-radius: 6px; padding: 12px 16px; margin: 15px 0;\">\n    <b style=\"color: #AB47BC; font-size: 16.5px; display: block; margin-bottom: 4px;\">📌 Definition (Radius of Gyration (k)):</b>\n    <p style=\"margin: 0; color: #FFFFFF; line-height: 1.6; font-size: 15.5px;\">The perpendicular distance from the axis of rotation to a point where the entire mass M of the body can be assumed to be concentrated without changing its moment of inertia.</p>\n  </div>\n\n  <div style=\"background: rgba(0,0,0,0.3); border: 1px solid rgba(171, 71, 188, 0.35); border-radius: 8px; padding: 10px 14px; text-align: center; margin: 14px 0; font-size: 15.5px; color: #FFFFFF; white-space: nowrap; overflow-x: auto;\"><b>I = M k<sup>2</sup> &nbsp; ⇒ &nbsp; k = √[ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ] = √[ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">r<sub>1</sub><sup>2</sup> + r<sub>2</sub><sup>2</sup> + ... + r<sub>N</sub><sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">N</span>\n  </span> ]</b> &nbsp; (SI Unit: <b>metre, m</b>)</div>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Radius of Gyration k Concept Model\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 450\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <radialGradient id=\"sphereGold8\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFFDE7\"/>\n      <stop offset=\"40%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"85%\" stop-color=\"#F57F17\"/>\n      <stop offset=\"100%\" stop-color=\"#E65100\"/>\n    </radialGradient>\n    <radialGradient id=\"sphereCyan8\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"40%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"85%\" stop-color=\"#00838F\"/>\n      <stop offset=\"100%\" stop-color=\"#004D40\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Left Side: Actual 3D Body -->\n  <g transform=\"translate(40, 20)\">\n    <text x=\"40\" y=\"30\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">1. Actual 3D Mass Distribution</text>\n\n    <!-- Axis Z-Z' -->\n    <line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"360\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"6,6\"/>\n    <text x=\"150\" y=\"40\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Z</text>\n    <text x=\"150\" y=\"380\" fill=\"#AB47BC\" font-family=\"sans-serif\" font-size=\"14\" font-weight=\"bold\">Z'</text>\n\n    <!-- 3D Volumetric Solid Shape -->\n    <path d=\"M 130 90 Q 300 60 270 230 Q 230 340 90 280 Q 60 160 130 90 Z\" fill=\"rgba(2,132,199,0.18)\" stroke=\"#38BDF8\" stroke-width=\"2.5\"/>\n\n    <!-- 3D Mass Particles m1, m2 -->\n    <circle cx=\"230\" cy=\"120\" r=\"8\" fill=\"url(#sphereGold8)\"/>\n    <line x1=\"160\" y1=\"120\" x2=\"230\" y2=\"120\" stroke=\"#94A3B8\" stroke-dasharray=\"3,3\"/>\n    <text x=\"180\" y=\"112\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"13.5\">m₁, r₁</text>\n\n    <circle cx=\"260\" cy=\"230\" r=\"9\" fill=\"url(#sphereCyan8)\"/>\n    <line x1=\"160\" y1=\"230\" x2=\"260\" y2=\"230\" stroke=\"#94A3B8\" stroke-dasharray=\"3,3\"/>\n    <text x=\"195\" y=\"222\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"13.5\">m₂, r₂</text>\n\n    <text x=\"60\" y=\"345\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"15.5\" font-weight=\"bold\">I = m₁r₁² + m₂r₂² + ...</text>\n  </g>\n\n  <!-- Equivalence Symbol -->\n  <g transform=\"translate(390, 190)\">\n    <text x=\"-15\" y=\"10\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"30\" font-weight=\"bold\">≡</text>\n  </g>\n\n  <!-- Right Side: Single Concentrated Mass M at Gyration Radius k -->\n  <g transform=\"translate(440, 20)\">\n    <text x=\"40\" y=\"30\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16.5\" font-weight=\"bold\">2. Concentrated Mass M at Radius k</text>\n\n    <!-- Axis Z-Z' -->\n    <line x1=\"160\" y1=\"50\" x2=\"160\" y2=\"360\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"6,6\"/>\n\n    <!-- 3D Mass M Sphere -->\n    <circle cx=\"280\" cy=\"200\" r=\"22\" fill=\"url(#sphereCyan8)\" stroke=\"#FFFFFF\" stroke-width=\"2\"/>\n    <text x=\"265\" y=\"170\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">Mass M</text>\n\n    <!-- Distance k Arrow -->\n    <line x1=\"160\" y1=\"200\" x2=\"280\" y2=\"200\" stroke=\"#FFD700\" stroke-width=\"4\"/>\n    <line x1=\"160\" y1=\"188\" x2=\"160\" y2=\"212\" stroke=\"#FFD700\" stroke-width=\"2\"/>\n    <line x1=\"280\" y1=\"188\" x2=\"280\" y2=\"212\" stroke=\"#FFD700\" stroke-width=\"2\"/>\n    <text x=\"210\" y=\"190\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"18.5\" font-weight=\"bold\">k</text>\n\n    <text x=\"80\" y=\"315\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">I = M k²</text>\n    <text x=\"80\" y=\"345\" fill=\"#76FF03\" font-family=\"monospace\" font-size=\"16.5\" font-weight=\"bold\">k = √( I / M )</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Volumetric model comparing actual body mass distribution vs concentrated mass M at radius k.\n    </div>\n  </div>\n\n  <!-- SECTION 10: VALUES OF MOMENTS OF INERTIA FOR SIMPLE GEOMETRICAL OBJECTS -->\n  <h2 style=\"color: #AB47BC; border-bottom: 2px solid #AB47BC; padding-bottom: 6px; margin-top: 30px;\">10. Moments of Inertia of Simple Geometrical Objects</h2>\n\n  \n  <div style=\"background: #0B0F19; border: 1.8px solid #AB47BC; border-radius: 16px; padding: 16px; margin: 24px 0; box-shadow: 0 10px 30px rgba(171, 71, 188, 0.25);\">\n    <div style=\"color: #AB47BC; font-weight: bold; font-size: 17px; margin-bottom: 12px; text-align: center; text-transform: uppercase; letter-spacing: 0.8px;\">\n      📍 Moments of Inertia Reference Set for Standard Bodies\n    </div>\n    <div style=\"width: 100%; max-width: 840px; margin: 0 auto; overflow: hidden; border-radius: 12px; border: 1px solid rgba(255,255,255,0.08);\">\n      \n<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 800 460\" width=\"100%\" height=\"100%\" style=\"background: linear-gradient(135deg, #0B0F19 0%, #111827 50%, #070A10 100%);\">\n  <defs>\n    <linearGradient id=\"ringGold3D9\" x1=\"0%\" y1=\"0%\" x2=\"100%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#FFFDE7\"/>\n      <stop offset=\"50%\" stop-color=\"#FFD700\"/>\n      <stop offset=\"100%\" stop-color=\"#B78103\"/>\n    </linearGradient>\n    <radialGradient id=\"discCyan3D9\" cx=\"40%\" cy=\"40%\" r=\"60%\">\n      <stop offset=\"0%\" stop-color=\"#E0F7FA\"/>\n      <stop offset=\"60%\" stop-color=\"#00E5FF\"/>\n      <stop offset=\"100%\" stop-color=\"#006064\"/>\n    </radialGradient>\n    <linearGradient id=\"rod3DGrad9\" x1=\"0%\" y1=\"0%\" x2=\"0%\" y2=\"100%\">\n      <stop offset=\"0%\" stop-color=\"#38BDF8\"/>\n      <stop offset=\"30%\" stop-color=\"#0284C7\"/>\n      <stop offset=\"70%\" stop-color=\"#0369A1\"/>\n      <stop offset=\"100%\" stop-color=\"#075985\"/>\n    </linearGradient>\n    <radialGradient id=\"sphere3DGrad9\" cx=\"35%\" cy=\"35%\" r=\"65%\">\n      <stop offset=\"0%\" stop-color=\"#FFD1D1\"/>\n      <stop offset=\"40%\" stop-color=\"#FF512F\"/>\n      <stop offset=\"85%\" stop-color=\"#DD2C00\"/>\n      <stop offset=\"100%\" stop-color=\"#801300\"/>\n    </radialGradient>\n  </defs>\n\n  <!-- Grid 2x2 of 3D Standard Bodies (Height 195px, Font 18px) -->\n\n  <!-- 1. 3D Thin Circular Ring -->\n  <g transform=\"translate(25, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#AB47BC\" stroke-width=\"1.5\"/>\n    <text x=\"20\" y=\"32\" fill=\"#00E5FF\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">1. Thin Circular Ring (Transverse Axis)</text>\n\n    <ellipse cx=\"120\" cy=\"120\" rx=\"68\" ry=\"30\" fill=\"none\" stroke=\"url(#ringGold3D9)\" stroke-width=\"8\"/>\n    <line x1=\"120\" y1=\"45\" x2=\"120\" y2=\"180\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"4,4\"/>\n\n    <text x=\"215\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">I = M R²</text>\n    <text x=\"215\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"15\">k = R</text>\n  </g>\n\n  <!-- 2. 3D Circular Disc -->\n  <g transform=\"translate(410, 20)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#AB47BC\" stroke-width=\"1.5\"/>\n    <text x=\"20\" y=\"32\" fill=\"#76FF03\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">2. Circular Disc (Transverse Axis)</text>\n\n    <ellipse cx=\"120\" cy=\"120\" rx=\"68\" ry=\"30\" fill=\"url(#discCyan3D9)\" stroke=\"#00E5FF\" stroke-width=\"2\"/>\n    <line x1=\"120\" y1=\"45\" x2=\"120\" y2=\"180\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"4,4\"/>\n\n    <text x=\"215\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">I = ½ M R²</text>\n    <text x=\"215\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"15\">k = R / √2</text>\n  </g>\n\n  <!-- 3. 3D Metallic Rod -->\n  <g transform=\"translate(25, 235)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#AB47BC\" stroke-width=\"1.5\"/>\n    <text x=\"20\" y=\"32\" fill=\"#FFD700\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">3. Metallic Rod (Central Axis)</text>\n\n    <rect x=\"45\" y=\"110\" width=\"150\" height=\"20\" rx=\"4\" fill=\"url(#rod3DGrad9)\" stroke=\"#38BDF8\" stroke-width=\"1\"/>\n    <line x1=\"120\" y1=\"45\" x2=\"120\" y2=\"180\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"4,4\"/>\n\n    <text x=\"215\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">I = <sup>1</sup>/₁₂ M L²</text>\n    <text x=\"215\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">End Axis: I = <sup>1</sup>/₃ M L²</text>\n  </g>\n\n  <!-- 4. 3D Volumetric Solid Sphere -->\n  <g transform=\"translate(410, 235)\">\n    <rect x=\"0\" y=\"0\" width=\"365\" height=\"195\" rx=\"12\" fill=\"rgba(255,255,255,0.03)\" stroke=\"#AB47BC\" stroke-width=\"1.5\"/>\n    <text x=\"20\" y=\"32\" fill=\"#FF512F\" font-family=\"sans-serif\" font-size=\"16\" font-weight=\"bold\">4. Solid Sphere (Diameter Axis)</text>\n\n    <circle cx=\"120\" cy=\"115\" r=\"45\" fill=\"url(#sphere3DGrad9)\"/>\n    <ellipse cx=\"120\" cy=\"115\" rx=\"45\" ry=\"14\" fill=\"none\" stroke=\"rgba(255,255,255,0.4)\" stroke-dasharray=\"3,3\"/>\n    <line x1=\"120\" y1=\"45\" x2=\"120\" y2=\"180\" stroke=\"#AB47BC\" stroke-width=\"3\" stroke-dasharray=\"4,4\"/>\n\n    <text x=\"215\" y=\"98\" fill=\"#FFFFFF\" font-family=\"monospace\" font-size=\"18\" font-weight=\"bold\">I = <sup>2</sup>/₅ M R²</text>\n    <text x=\"215\" y=\"130\" fill=\"#94A3B8\" font-family=\"sans-serif\" font-size=\"14\">Hollow: I = <sup>2</sup>/₃ M R²</text>\n  </g>\n</svg>\n    </div>\n    <div style=\"color: #CBD5E1; font-size: 14px; text-align: center; margin-top: 12px; line-height: 1.5; font-weight: 500;\">\n      💡 3D Rendered reference set for Thin Ring, Circular Disc, Metallic Rod, and Solid Sphere showing rotation axes.\n    </div>\n  </div>\n\n  <!-- QUICK REVISION CHEAT SHEET (PLACED AT THE VERY END OF OVERVIEW SECTION) -->\n  <div style=\"background: rgba(171, 71, 188, 0.05); border: 1.5px solid #AB47BC; border-radius: 12px; padding: 16px; margin-top: 35px; margin-bottom: 15px;\">\n    <h2 class=\"text-center\" style=\"color: #AB47BC; margin: 0 0 6px 0; font-size: 20px; font-weight: bold; text-align: center !important;\">⚡ Quick Revision Cheat Sheet</h2>\n    <p class=\"text-center\" style=\"color: #AB47BC; margin: 0 0 16px 0; font-size: 14.5px; text-align: center !important;\">Key Formulae, Rotational Identities & Moments of Inertia Summary for Unit V</p>\n\n    <div style=\"display: grid; grid-template-columns: repeat(auto-fit, minmax(280px, 1fr)); gap: 10px; font-size: 14px;\">\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Centre of Mass Position:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">2-Particle: R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span><br>Rod (Length L): X<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Torque & Angular Momentum:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">τ = r × F = I α &nbsp;|&nbsp; L = r × p = I ω<br>τ<sub>ext</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">dL</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">dt</span>\n  </span> &nbsp;|&nbsp; τ<sub>ext</sub> = 0 ⇒ L = I ω = Const.</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Rotational Kinematics:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">ω = ω<sub>0</sub> + α t &nbsp;|&nbsp; θ = ω<sub>0</sub> t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> α t<sup>2</sup><br>ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Rotational Kinetic Energy & Power:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">E<sub>rot</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> I ω<sup>2</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 I</span>\n  </span><br>Power P = τ ω</span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Standard Moments of Inertia:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">Ring (CM): MR<sup>2</sup> &nbsp;|&nbsp; Disc (CM): <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> MR<sup>2</sup><br>Rod (CM): <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">12</span>\n  </span> ML<sup>2</sup> &nbsp;|&nbsp; Sphere: <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span> MR<sup>2</sup></span>\n      </div>\n      <div style=\"background: rgba(0,0,0,0.25); padding: 10px 12px; border-left: 3.5px solid #AB47BC; border-radius: 6px;\">\n        <b style='color: #AB47BC; display: block; margin-bottom: 3px;'>• Radius of Gyration Formula:</b>\n        <span style=\"color: #FFFFFF; line-height: 1.6; display: block;\">I = M k<sup>2</sup> &nbsp; ⇒ &nbsp; k = √[ <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">I</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> ]</span>\n      </div>\n    </div>\n  </div>\n\n</div>\n";

export const c11Phy5HtmlSolutions = "\n<style>\n  p, li, div:not(.table-container):not(.table-responsive):not(.pt-scroll-wrapper):not(.mcq-option) {\n    text-align: justify !important;\n  }\n  h1, h2, h3, h4, h5, h6 { text-align: left; }\n  .text-center { text-align: center !important; }\n  .text-left { text-align: left !important; }\n</style>\n\n<div style=\"padding: 12px; color: #E0E0E0; text-align: justify; font-family: system-ui, -apple-system, sans-serif; line-height: 1.7; font-size: 16px;\">\n  \n  <div style=\"text-align: center; margin-bottom: 25px; border-bottom: 2px solid #AB47BC; padding-bottom: 10px;\">\n    <h2 style=\"color: #AB47BC; margin: 0; font-size: 22px; font-weight: bold; text-align: center !important;\">NCERT & Master Solutions Guide</h2>\n    <p style=\"color: #B0BEC5; margin: 5px 0 0 0; font-size: 15px; text-align: center !important;\">Unit V: Motion of System of Particles and Rigid Body — 100 Master Practice Questions (Theoretical & Numerical)</p>\n  </div>\n<h3 style=\"color: #AB47BC; border-left: 4px solid #AB47BC; padding-left: 10px; margin-top: 25px;\">Part A: Multiple Choice Questions (Q1 - Q25)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q1: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The Centre of Mass of a two-particle system lies on the line joining the particles and:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Always lies at exact midpoint</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Divides distance inversely as their masses</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Divides distance directly as their masses</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Lies outside the joining line</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) Divides distance inversely as their masses</span></b><br>m<sub>1</sub> r<sub>1</sub> = m<sub>2</sub> r<sub>2</sub> ⇒ r<sub>1</sub> / r<sub>2</sub> = m<sub>2</sub> / m<sub>1</sub> (closer to heavier mass).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q2: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Internal forces acting between particles of a system can change:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Linear momentum of CM</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Total kinetic energy of system</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Velocity of CM</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Acceleration of CM</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) Total kinetic energy of system</span></b><br>Internal forces cancel out in pairs for momentum/CM motion (∑ F<sub>int</sub> = 0), but can do net internal work altering total kinetic energy.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q3: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The location of Centre of Mass of a uniform thin rod of length L from one end is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) L / 4</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) L / 3</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) L / 2</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 2 L / 3</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) L / 2</span></b><br>By symmetry, CM of a uniform rod lies at its geometric midpoint X<sub>cm</sub> = L/2.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q4: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The rotational analogue of force in rotational motion is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Angular momentum</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Moment of inertia</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Torque</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Angular velocity</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) Torque</span></b><br>Torque τ = I α is the rotational counterpart of linear force F = m a.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q5: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The rotational analogue of mass (inertia) is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Torque</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Moment of inertia</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Angular acceleration</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Angular momentum</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) Moment of inertia</span></b><br>Moment of inertia I measures rotational inertia of a body about a given axis.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q6: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The SI unit of Torque is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) N s</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) N m</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) J s</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) kg m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) N m</span></b><br>Torque τ = r × F, so its unit is Newton metre (N m).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q7: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The SI unit of Angular Momentum is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) N m</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) kg m<sup>2</sup> s<sup>-1</sup> (or J s)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) kg m s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) N m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) kg m<sup>2</sup> s<sup>-1</sup> (or J s)</span></b><br>L = r × p = [L] [M L T<sup>-1</sup>] = kg m<sup>2</sup> s<sup>-1</sup> = J s.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q8: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The relationship between Torque τ and Angular Momentum L is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) τ = L / t</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) τ = dL / dt</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) L = dτ / dt</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) τ = L × ω</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) τ = dL / dt</span></b><br>Torque equals time rate of change of angular momentum (rotational analogue of F = dp/dt).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q9: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">When a spinning ice skater pulls her arms inward, her angular speed ω increases because her:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Torque increases</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Moment of inertia decreases</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Mass increases</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Angular momentum increases</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) Moment of inertia decreases</span></b><br>By conservation of angular momentum L = I ω = constant. Pulling arms in decreases I, so ω increases.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q10: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A rigid body is in complete mechanical equilibrium when:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) ∑ F<sub>ext</sub> = 0 only</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) ∑ τ<sub>ext</sub> = 0 only</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Both ∑ F<sub>ext</sub> = 0 and ∑ τ<sub>ext</sub> = 0</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Velocity is zero</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) Both ∑ F<sub>ext</sub> = 0 and ∑ τ<sub>ext</sub> = 0</span></b><br>Complete equilibrium requires zero translational acceleration (∑ F = 0) AND zero rotational acceleration (∑ τ = 0).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q11: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A couple acting on a rigid body produces:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Pure translation</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Pure rotation</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Both translation and rotation</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) No motion</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) Pure rotation</span></b><br>A couple consists of equal and opposite non-collinear forces (∑ F = 0, ∑ τ ≠ 0), causing pure rotation without translation.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q12: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The third equation of rotational motion with constant angular acceleration α is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) ω = ω<sub>0</sub> + α t</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) θ = ω<sub>0</sub> t + 1/2 α t<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) τ = I α</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ</span></b><br>Rotational analogue of v<sup>2</sup> - u<sup>2</sup> = 2 a s.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q13: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The rotational kinetic energy of a body of moment of inertia I rotating at angular speed ω is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) I ω</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1/2 I ω</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/2 I ω<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) I ω<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) 1/2 I ω<sup>2</sup></span></b><br>Rotational K.E. E<sub>rot</sub> = 1/2 I ω<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q14: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Moment of inertia of a thin circular ring of mass M and radius R about its transverse central axis is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1/2 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/4 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 2/5 M R<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) M R<sup>2</sup></span></b><br>For a ring, all mass elements are at distance R from central transverse axis, so I = ∫ R<sup>2</sup> dm = M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q15: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Moment of inertia of a uniform circular disc of mass M and radius R about its transverse central axis is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1/2 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/4 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 2/5 M R<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) 1/2 M R<sup>2</sup></span></b><br>For a disc, I = 1/2 M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q16: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Moment of inertia of a solid sphere of mass M and radius R about its diameter is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1/2 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 2/3 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 2/5 M R<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 7/5 M R<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) 2/5 M R<sup>2</sup></span></b><br>For a solid sphere about diameter, I = 2/5 M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q17: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Moment of inertia of a thin uniform rod of mass M and length L about an axis through its CM perpendicular to length is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1/3 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1/12 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/2 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) M L<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) 1/12 M L<sup>2</sup></span></b><br>For a thin rod about central transverse axis, I = 1/12 M L<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q18: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Moment of inertia of a thin uniform rod of mass M and length L about an axis through one end perpendicular to length is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 1/12 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 1/3 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/4 M L<sup>2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) M L<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) 1/3 M L<sup>2</sup></span></b><br>For a thin rod about end transverse axis, I = 1/3 M L<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q19: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Radius of gyration k of a body of mass M and moment of inertia I is defined by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) k = I / M</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) k = √(I / M)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) k = I M</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) k = √(I M)</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) k = √(I / M)</span></b><br>From I = M k<sup>2</sup>, k = √(I / M).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q20: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Radius of gyration of a solid sphere of radius R about its diameter is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) R</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) R / √2</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) √(2/5) R</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) √(2/3) R</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) √(2/5) R</span></b><br>I = 2/5 M R<sup>2</sup> = M k<sup>2</sup> ⇒ k = √(2/5) R.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q21: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If net external force on a system of particles is zero, the Centre of Mass:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) Must be at rest</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) Must accelerate</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) Moves with constant velocity or remains at rest</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) Rotates continuously</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">c) Moves with constant velocity or remains at rest</span></b><br>F<sub>ext</sub> = 0 ⇒ M A<sub>cm</sub> = 0 ⇒ V<sub>cm</sub> = Constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q22: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">The work done by a torque τ in rotating a body through angular displacement θ is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) τ / θ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) τ θ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 1/2 τ θ</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) τ θ<sup>2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) τ θ</span></b><br>Rotational work W = ∫ τ dθ = τ θ (for constant torque).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q23: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Angular momentum L and rotational kinetic energy E<sub>rot</sub> are related by:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) E<sub>rot</sub> = L<sup>2</sup> / (2 I)</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) E<sub>rot</sub> = L I</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) E<sub>rot</sub> = L<sup>2</sup> I</div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) E<sub>rot</sub> = L / (2 I)</div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">a) E<sub>rot</sub> = L<sup>2</sup> / (2 I)</span></b><br>E<sub>rot</sub> = 1/2 I ω<sup>2</sup> = 1/2 I (L / I)<sup>2</sup> = L<sup>2</sup> / (2 I).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q24: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A wheel of radius 0.5 m rolls without slipping. If angular velocity is 10 rad s<sup>-1</sup>, linear speed of CM is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 5 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 10 m s<sup>-1</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 20 m s<sup>-1</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) 5 m s<sup>-1</sup></span></b><br>v<sub>cm</sub> = r ω = 0.5 × 10 = 5 m s<sup>-1</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q25: Multiple Choice Question</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A fly-wheel increases its angular speed from 10 rad s<sup>-1</sup> to 30 rad s<sup>-1</sup> in 5 s. Angular acceleration is:<div style=\"margin: 12px 0; text-align: left !important; line-height: 1.8; color: #FFCC80;\">\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">a) 2 rad s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">b) 4 rad s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">c) 6 rad s<sup>-2</sup></div>\n    <div class=\"mcq-option\" style=\"text-align: left !important; margin: 4px 0;\">d) 8 rad s<sup>-2</sup></div>\n  </div></div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Correct Answer: <span style=\"color: #AB47BC;\">b) 4 rad s<sup>-2</sup></span></b><br>α = (ω - ω<sub>0</sub>)/t = (30 - 10)/5 = 20 / 5 = 4 rad s<sup>-2</sup>.\n    </div>\n  </div><h3 style=\"color: #AB47BC; border-left: 4px solid #AB47BC; padding-left: 10px; margin-top: 35px;\">Part B: Very Short Answer Questions (Q26 - Q55)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q26: Define Centre of Mass</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define Centre of Mass of a system.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Centre of Mass is the single point in space where total mass of system is concentrated and where net external force produces translational acceleration.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q27: Centre of Mass 2-Particle Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for position vector R<sub>cm</sub> of a 2-particle system.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      R<sub>cm</sub> = (m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub>) / (m<sub>1</sub> + m<sub>2</sub>).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q28: Define Rigid Body</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is an ideal rigid body?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A rigid body is a body with a fixed shape where inter-particle distances remain strictly constant under external forces.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q29: Define Torque</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define torque and state its SI unit.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Torque is the rotational turning effect of force: τ = r × F = |r||F| sin θ n̂. SI unit: N m.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q30: Define Angular Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angular momentum and state its SI unit.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angular momentum is moment of linear momentum: L = r × p = I ω. SI unit: kg m<sup>2</sup> s<sup>-1</sup> (or J s).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q31: Torque and Angular Momentum Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State differential relation between Torque and Angular Momentum.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      τ<sub>ext</sub> = dL / dt.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q32: State Conservation of Angular Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State Law of Conservation of Angular Momentum.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      If net external torque τ<sub>ext</sub> = 0, total angular momentum L = I ω remains strictly constant.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q33: Define Moment of Inertia</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define moment of inertia of a body.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Moment of inertia is rotational inertia of a body about an axis: I = ∑ m<sub>i</sub> r<sub>i</sub><sup>2</sup> = ∫ r<sup>2</sup> dm. SI unit: kg m<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q34: Define Radius of Gyration</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define radius of gyration k.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Radius of gyration is perpendicular distance from rotation axis to point where total body mass can be concentrated: k = √(I / M).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q35: Define Couple</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">What is a couple in rotational mechanics?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      A couple is a pair of equal, opposite, non-collinear parallel forces acting on a body that produces pure rotation.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q36: Moment of a Couple Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for torque of a couple.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Torque of couple = Force × Perpendicular distance between force lines (F × d).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q37: Condition for Translational Equilibrium</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State condition for translational equilibrium of a rigid body.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Vector sum of all external forces must be zero: ∑ F<sub>ext</sub> = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q38: Condition for Rotational Equilibrium</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State condition for rotational equilibrium of a rigid body.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Vector sum of all external torques about any axis must be zero: ∑ τ<sub>ext</sub> = 0.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q39: First Rotational Kinematic Equation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State first equation of rotational motion with constant α.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      ω = ω<sub>0</sub> + α t.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q40: Second Rotational Kinematic Equation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State second equation of rotational motion.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      θ = ω<sub>0</sub> t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> α t<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q41: Third Rotational Kinematic Equation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State third equation of rotational motion.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q42: Rotational Kinetic Energy Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for rotational kinetic energy.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      E<sub>rot</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> I ω<sup>2</sup> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">L<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2 I</span>\n  </span>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q43: Rotational Power Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State formula for rotational power P.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      P = τ · ω = τ ω cos θ.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q44: Moment of Inertia of Ring (CM)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of thin ring of mass M, radius R about transverse CM axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q45: Moment of Inertia of Disc (CM)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of uniform disc of mass M, radius R about transverse CM axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q46: Moment of Inertia of Rod (CM)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of thin rod of mass M, length L about transverse CM axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">12</span>\n  </span> M L<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q47: Moment of Inertia of Rod (End)</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of thin rod of mass M, length L about transverse axis through end.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> M L<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q48: Moment of Inertia of Solid Sphere</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of solid sphere of mass M, radius R about diameter.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">5</span>\n  </span> M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q49: Moment of Inertia of Spherical Shell</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of hollow spherical shell about diameter.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">2</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">3</span>\n  </span> M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q50: Moment of Inertia of Solid Cylinder</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State MI of solid cylinder of mass M, radius R about central axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> M R<sup>2</sup>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q51: Linear vs Angular Velocity Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write vector relation between linear velocity v, angular velocity ω, and radius vector r.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      v = ω × r &nbsp; (Magnitude: v = r ω).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q52: Linear vs Angular Acceleration Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write relation between tangential acceleration a<sub>t</sub> and angular acceleration α.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      a<sub>t</sub> = r α.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q53: Does CM of Body Always Lie Inside It?</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Does Centre of Mass of a body necessarily lie inside its material body?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      No! For hollow objects like a ring or hollow sphere, Centre of Mass lies in empty space outside material body.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q54: Internal Forces Effect on CM</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Can internal forces accelerate Centre of Mass of a system?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      No! Internal forces cancel out in pairs by Newton's Third Law, so only external forces accelerate CM.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q55: Dimension of Moment of Inertia</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State dimensional formula of Moment of Inertia.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Dimensions of MI = [M<sup>1</sup> L<sup>2</sup> T<sup>0</sup>].\n    </div>\n  </div><h3 style=\"color: #AB47BC; border-left: 4px solid #AB47BC; padding-left: 10px; margin-top: 35px;\">Part C: Short Answer Questions (Q56 - Q85)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q56: Centre of Mass of 2 Particles Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Two particles of masses 2 kg and 3 kg are placed 1 m apart along x-axis. Find location of CM from 2 kg particle.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let origin be at 2 kg mass (x<sub>1</sub> = 0), m<sub>2</sub> = 3 kg at x<sub>2</sub> = 1 m.<br>X<sub>cm</sub> = (m<sub>1</sub> x<sub>1</sub> + m<sub>2</sub> x<sub>2</sub>) / (m<sub>1</sub> + m<sub>2</sub>) = (2×0 + 3×1) / (2 + 3) = 3 / 5 = <b>0.6 metres (60 cm from 2 kg particle)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q57: Derive Centre of Mass of Uniform Rod</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expression for Centre of Mass of a uniform thin rod of length L and mass M.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Linear density λ = M/L. Take element dx at position x from one end.<br>Mass element dm = λ dx = (M/L) dx.<br>X<sub>cm</sub> = (1/M) ∫<sub>0</sub><sup>L</sup> x dm = (1/M) ∫<sub>0</sub><sup>L</sup> x (M/L) dx = (1/L) [ x<sup>2</sup>/2 ]<sub>0</sub><sup>L</sup> = (1/L) (L<sup>2</sup>/2) = <b>L / 2 (Midpoint)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q58: Torque Vector Calculation Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Position vector r = 2 î + 3 ĵ m and Force F = 4 î + 5 ĵ N. Calculate torque vector τ.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      τ = r × F = (2 î + 3 ĵ) × (4 î + 5 ĵ) = 2(5)(î×ĵ) + 3(4)(ĵ×î) = 10 k̂ - 12 k̂ = <b>-2 k̂ N m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q59: Angular Momentum Vector Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Particle of mass 2 kg moves at v = 3 î + 4 ĵ m s<sup>-1</sup> at position r = 5 î m. Find angular momentum L.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Linear momentum p = m v = 2 (3 î + 4 ĵ) = 6 î + 8 ĵ kg m s<sup>-1</sup>.<br>L = r × p = (5 î) × (6 î + 8 ĵ) = 40 (î × ĵ) = <b>40 k̂ kg m<sup>2</sup> s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q60: Spinning Ice Skater Reasoning</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain using conservation of angular momentum why a spinning skater speeds up when pulling arms inward.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Net external torque τ<sub>ext</sub> = 0, so L = I ω = constant.<br>Pulling arms inward brings mass closer to rotation axis, reducing moment of inertia (I<sub>2</sub> < I<sub>1</sub>).<br>Since I<sub>1</sub> ω<sub>1</sub> = I<sub>2</sub> ω<sub>2</sub>, angular velocity ω<sub>2</sub> = (I<sub>1</sub>/I<sub>2</sub>) ω<sub>1</sub> > ω<sub>1</sub> (Spin speed increases!).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q61: Flywheel Torque and Angular Acceleration Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A flywheel of moment of inertia I = 5 kg m<sup>2</sup> is acted upon by torque τ = 20 N m. Find angular acceleration α.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      τ = I α ⇒ α = τ / I = 20 / 5 = <b>4 rad s<sup>-2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q62: Rotational Kinematics Problem 1</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A wheel starting from rest accelerates uniformly at α = 2 rad s<sup>-2</sup> for 6 s. Find final angular speed and angular displacement.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) Final angular speed: ω = ω<sub>0</sub> + α t = 0 + 2(6) = <b>12 rad s<sup>-1</sup></b>.<br>(ii) Displacement: θ = ω<sub>0</sub> t + 1/2 α t<sup>2</sup> = 0 + 1/2 (2) (36) = <b>36 radians</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q63: Rotational Kinetic Energy Calculation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A solid sphere of mass 5 kg and radius 0.2 m rotates at 10 rad s<sup>-1</sup> about diameter. Find its rotational kinetic energy.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      I = 2/5 M R<sup>2</sup> = 2/5 (5) (0.2<sup>2</sup>) = 2 (0.04) = 0.08 kg m<sup>2</sup>.<br>E<sub>rot</sub> = 1/2 I ω<sup>2</sup> = 1/2 (0.08) (10<sup>2</sup>) = 0.04 × 100 = <b>4 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q64: Radius of Gyration of Disc vs Ring</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Compare radius of gyration of a uniform disc and a thin ring of same mass and radius about transverse central axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Ring: I<sub>ring</sub> = M R<sup>2</sup> = M k<sub>1</sub><sup>2</sup> ⇒ <b>k<sub>1</sub> = R</b>.<br>Disc: I<sub>disc</sub> = 1/2 M R<sup>2</sup> = M k<sub>2</sub><sup>2</sup> ⇒ <b>k<sub>2</sub> = R / √2</b>.<br>Ratio k<sub>ring</sub> / k<sub>disc</sub> = R / (R / √2) = <b>√2 : 1</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q65: Couple Forces Torque Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Show that torque of a couple is independent of the choice of origin.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Forces F at r<sub>1</sub> and -F at r<sub>2</sub>.<br>Total torque τ = (r<sub>1</sub> × F) + (r<sub>2</sub> × -F) = (r<sub>1</sub> - r<sub>2</sub>) × F = d × F.<br>Since relative vector d = r<sub>1</sub> - r<sub>2</sub> is fixed between forces, torque of couple depends ONLY on separation d, not origin!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q66: CM of 3 Particles at Vertices of Equilateral Triangle</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Three equal masses m placed at vertices of equilateral triangle of side a: (0,0), (a,0), (a/2, a√3/2). Find CM coordinates.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      X<sub>cm</sub> = (m×0 + m×a + m×a/2) / (3m) = (1.5 m a) / (3m) = <b>a / 2</b>.<br>Y<sub>cm</sub> = (m×0 + m×0 + m×a√3/2) / (3m) = (a√3/2) / 3 = <b>a / (2√3)</b>.<br>CM is at centroid <b>(a/2, a/(2√3))</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q67: Rotational Work and Power Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A constant torque of 50 N m turns a wheel at constant angular velocity 20 rad s<sup>-1</sup>. Find work done in 10 s and power delivered.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angular displacement θ = ω t = 20 × 10 = 200 radians.<br>Work W = τ θ = 50 × 200 = <b>10,000 Joules (10 kJ)</b>.<br>Power P = τ ω = 50 × 20 = <b>1000 Watts (1 kW)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q68: Angular Momentum Conservation Collision Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A disc of moment of inertia I<sub>1</sub> = 2 kg m<sup>2</sup> rotating at 30 rad s<sup>-1</sup> drops onto a stationary disc of I<sub>2</sub> = 1 kg m<sup>2</sup>. Find common angular speed.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      By conservation of angular momentum: I<sub>1</sub> ω<sub>1</sub> = (I<sub>1</sub> + I<sub>2</sub>) ω.<br>2 (30) = (2 + 1) ω ⇒ 60 = 3 ω ⇒ <b>Common ω = 20 rad s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q69: CM Motion in Explosive Decay</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A projectile of mass 10 kg moving at 20 m s<sup>-1</sup> explodes mid-air into 4 kg and 6 kg pieces. If 4 kg piece moves forward at 50 m s<sup>-1</sup>, find velocity of 6 kg piece.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total momentum before = 10 × 20 = 200 kg m s<sup>-1</sup>.<br>200 = 4(50) + 6 v<sub>2</sub> ⇒ 200 = 200 + 6 v<sub>2</sub> ⇒ 6 v<sub>2</sub> = 0 ⇒ <b>v<sub>2</sub> = 0 m s<sup>-1</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q70: Moment of Inertia of Thin Rod about End Formula Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive MI of thin uniform rod of mass M, length L about transverse axis through one end using integration.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Linear density λ = M/L. Axis at x = 0, rod extends from x = 0 to x = L.<br>I = ∫<sub>0</sub><sup>L</sup> x<sup>2</sup> dm = ∫<sub>0</sub><sup>L</sup> x<sup>2</sup> (M/L) dx = (M/L) [ x<sup>3</sup>/3 ]<sub>0</sub><sup>L</sup> = (M/L) (L<sup>3</sup>/3) = <b>1/3 M L<sup>2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q71: Moment of Inertia of Ring about Diameter</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Using symmetry, find moment of inertia of a thin circular ring of mass M and radius R about its diameter.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let I<sub>z</sub> = M R<sup>2</sup> be MI about transverse axis through center.<br>By perpendicular axis symmetry for planar ring: I<sub>z</sub> = I<sub>x</sub> + I<sub>y</sub> = 2 I<sub>diameter</sub>.<br>2 I<sub>diameter</sub> = M R<sup>2</sup> ⇒ <b>I<sub>diameter</sub> = 1/2 M R<sup>2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q72: Rotational Impulse Concept</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define angular (rotational) impulse and state its relation to angular momentum change.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Angular impulse is product of average torque and time interval: Rotational Impulse = ∫ τ dt = ΔL = L<sub>final</sub> - L<sub>initial</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q73: Rolling Motion Total Kinetic Energy Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write total kinetic energy formula for a body of mass M, radius R, radius of gyration k rolling without slipping at speed v.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total K.E. = E<sub>trans</sub> + E<sub>rot</sub> = 1/2 M v<sup>2</sup> + 1/2 I ω<sup>2</sup>.<br>Substitute I = M k<sup>2</sup> and ω = v/R:<br>Total K.E. = <b>1/2 M v<sup>2</sup> [ 1 + (k<sup>2</sup> / R<sup>2</sup>) ]</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q74: Rolling Disc Total Kinetic Energy Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find fraction of total kinetic energy that is rotational for a uniform disc rolling without slipping.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For disc: k<sup>2</sup>/R<sup>2</sup> = 1/2.<br>E<sub>rot</sub> = 1/2 I ω<sup>2</sup> = 1/2 (1/2 M R<sup>2</sup>) (v/R)<sup>2</sup> = 1/4 M v<sup>2</sup>.<br>Total K.E. = 1/2 M v<sup>2</sup> (1 + 1/2) = 3/4 M v<sup>2</sup>.<br>Fraction E<sub>rot</sub> / E<sub>total</sub> = (1/4 M v<sup>2</sup>) / (3/4 M v<sup>2</sup>) = <b>1 / 3 (33.3%)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q75: Angular Acceleration from Stopping Revolutions Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A grinding wheel running at 600 rpm is brought to rest in 10 s. Find angular retardation and revolutions completed.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial ω<sub>0</sub> = 600 rpm = 600 × (2π/60) = 20π rad s<sup>-1</sup>.<br>α = (0 - 20π) / 10 = <b>-2π rad s<sup>-2</sup> ≈ -6.28 rad s<sup>-2</sup></b>.<br>Displacement θ = (ω<sub>0</sub> + ω)/2 × t = (20π / 2) × 10 = 100π radians.<br>Revolutions = 100π / (2π) = <b>50 revolutions</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q76: Why Spokes are Provided in Bicycle Wheels</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Why are bicycle wheels provided with spokes and heavy rim?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Spokes place most mass near outer rim at distance R, maximizing moment of inertia I = M R<sup>2</sup>. High I maintains uniform motion and resists sudden speed fluctuations!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q77: Equilibrium Ladder Problem</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 10 kg uniform ladder of length 4 m leans against smooth wall at 60° to horizontal floor. Find normal reaction from wall.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Torque about base on floor: N<sub>wall</sub> (L sin 60°) - mg (L/2 cos 60°) = 0.<br>N<sub>wall</sub> (4 × √3/2) = 100 (2 × 0.5) ⇒ N<sub>wall</sub> (2√3) = 100.<br>N<sub>wall</sub> = 100 / (2√3) = 50 / √3 ≈ <b>28.87 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q78: Linear Momentum of CM System Formula</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Express total linear momentum P of an N-particle system in terms of total mass M and velocity of CM V<sub>cm</sub>.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      P<sub>total</sub> = ∑ m<sub>i</sub> v<sub>i</sub> = M V<sub>cm</sub>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q79: Relation between Rotational KE and Angular Momentum Derivation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive E<sub>rot</sub> = L<sup>2</sup> / (2 I).</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      E<sub>rot</sub> = 1/2 I ω<sup>2</sup>. Multiply numerator and denominator by I:<br>E<sub>rot</sub> = (I<sup>2</sup> ω<sup>2</sup>) / (2 I) = (I ω)<sup>2</sup> / (2 I).<br>Since L = I ω: <b>E<sub>rot</sub> = L<sup>2</sup> / (2 I)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q80: CM of L-shaped Thin Uniform Sheet</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Find CM of an L-shaped uniform lamina cut from a 2m × 2m square sheet missing one 1m × 1m corner.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Lamina consists of three 1m × 1m squares of mass m each at (0.5, 0.5), (1.5, 0.5), and (0.5, 1.5).<br>X<sub>cm</sub> = (m×0.5 + m×1.5 + m×0.5) / 3m = 2.5 / 3 = <b>5/6 m ≈ 0.833 m</b>.<br>Y<sub>cm</sub> = (m×0.5 + m×0.5 + m×1.5) / 3m = 2.5 / 3 = <b>5/6 m ≈ 0.833 m</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q81: Torque required to stop rotating disc</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A disc of I = 2 kg m<sup>2</sup> rotating at 50 rad s<sup>-1</sup> is stopped in 5 s. Find retarding torque.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      α = (0 - 50) / 5 = -10 rad s<sup>-2</sup>.<br>Torque τ = I α = 2 × (-10) = <b>-20 N m (Magnitude 20 N m)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q82: Moment of Inertia Factors</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State 3 factors on which the moment of inertia of a body depends.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      1. Mass of the body.<br>2. Distribution of mass relative to axis of rotation.<br>3. Position and orientation of the axis of rotation.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q83: Moment of Inertia of Hollow vs Solid Cylinder</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Which has a larger moment of inertia about central axis: a solid cylinder or hollow cylinder of same mass M and radius R?</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Hollow cylinder has larger MI (I = M R<sup>2</sup>) than solid cylinder (I = 1/2 M R<sup>2</sup>) because all mass of hollow cylinder is at maximum distance R from axis.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q84: Angular Velocity Ratio for Earth Shrinking</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">If Earth suddenly shrinks to half its radius without mass change, find new duration of day.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Solid sphere I = 2/5 M R<sup>2</sup>. If R becomes R/2, I<sub>2</sub> = I<sub>1</sub> / 4.<br>By conservation of L: I<sub>1</sub> ω<sub>1</sub> = I<sub>2</sub> ω<sub>2</sub> ⇒ I<sub>1</sub> (2π/T<sub>1</sub>) = (I<sub>1</sub>/4) (2π/T<sub>2</sub>).<br>T<sub>2</sub> = T<sub>1</sub> / 4 = 24 hours / 4 = <b>6 hours!</b>\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q85: Deceleration of Rolling Sphere on Incline</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Write acceleration formula of a solid sphere rolling down an incline of angle θ.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">g sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 + k<sup>2</sup>/R<sup>2</sup></span>\n  </span>. For solid sphere k<sup>2</sup>/R<sup>2</sup> = 2/5:<br>a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">g sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 + 2/5</span>\n  </span> = <b>5/7 g sin θ</b>.\n    </div>\n  </div><h3 style=\"color: #AB47BC; border-left: 4px solid #AB47BC; padding-left: 10px; margin-top: 35px;\">Part D: Long Answer Questions (Q86 - Q100)</h3>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q86: Derivation of Centre of Mass for 2-Particle & N-Particle System</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define Centre of Mass. Derive the position vector expression R<sub>cm</sub> = (m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub>)/(m<sub>1</sub> + m<sub>2</sub>) for a two-particle system and extend it to N particles.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Definition:</b> The Centre of Mass is the point where total system mass is concentrated for describing translational motion.<br><br><b>Derivation for 2 Particles:</b><br>Let particles m<sub>1</sub>, m<sub>2</sub> have position vectors r<sub>1</sub>, r<sub>2</sub>.<br>Newton's 2nd Law for particle 1: F<sub>1</sub><sup>ext</sup> + F<sub>12</sub> = m<sub>1</sub> (d<sup>2</sup>r<sub>1</sub>/dt<sup>2</sup>).<br>Newton's 2nd Law for particle 2: F<sub>2</sub><sup>ext</sup> + F<sub>21</sub> = m<sub>2</sub> (d<sup>2</sup>r<sub>2</sub>/dt<sup>2</sup>).<br>Adding equations and applying F<sub>12</sub> + F<sub>21</sub> = 0 (Newton's 3rd Law):<br>F<sub>ext</sub> = m<sub>1</sub> (d<sup>2</sup>r<sub>1</sub>/dt<sup>2</sup>) + m<sub>2</sub> (d<sup>2</sup>r<sub>2</sub>/dt<sup>2</sup>) = d<sup>2</sup>/dt<sup>2</sup> [ m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub> ].<br>Define total mass M = m<sub>1</sub> + m<sub>2</sub> and write F<sub>ext</sub> = M (d<sup>2</sup>R<sub>cm</sub>/dt<sup>2</sup>):<br>M R<sub>cm</sub> = m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub> &nbsp; ⇒ &nbsp; <b>R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">m<sub>1</sub> + m<sub>2</sub></span>\n  </span></b>.<br><br><b>Extension to N Particles:</b><br><b>R<sub>cm</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">∑ m<sub>i</sub> r<sub>i</sub></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">M</span>\n  </span> (m<sub>1</sub> r<sub>1</sub> + m<sub>2</sub> r<sub>2</sub> + ... + m<sub>N</sub> r<sub>N</sub>)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q87: Complete Theory & Derivation of Torque and Angular Momentum Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Define Torque τ and Angular Momentum L. Derive the differential relation τ = dL/dt and prove conservation of angular momentum.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Definitions:</b><br>- Torque: τ = r × F (rotational turning force).<br>- Angular Momentum: L = r × p (moment of momentum).<br><br><b>Derivation of τ = dL/dt:</b><br>L = r × p. Differentiating with respect to time t:<br>dL/dt = d(r × p)/dt = (dr/dt × p) + (r × dp/dt).<br>Since dr/dt = v and p = m v, (v × m v) = m (v × v) = 0.<br>And dp/dt = F<sub>ext</sub>:<br>dL/dt = 0 + (r × F<sub>ext</sub>) = <b>τ<sub>ext</sub></b>.<br><br><b>Proof of Conservation Law:</b><br>If net external torque τ<sub>ext</sub> = 0, then dL/dt = 0.<br>Integrating yields: <b>L = I ω = Constant</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q88: Derivation of 3 Equations of Rotational Motion</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive the three equations of rotational motion (ω = ω<sub>0</sub> + α t, θ = ω<sub>0</sub> t + 1/2 α t<sup>2</sup>, ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ) for constant angular acceleration α.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a rigid body rotating with constant angular acceleration α, initial angular velocity ω<sub>0</sub> at t = 0, final angular velocity ω at time t, and angular displacement θ.<br><br><b>(i) First Equation (ω = ω<sub>0</sub> + α t):</b><br>By definition α = dω / dt ⇒ dω = α dt.<br>Integrating: ∫<sub>ω0</sub><sup>ω</sup> dω = α ∫<sub>0</sub><sup>t</sup> dt ⇒ ω - ω<sub>0</sub> = α t &nbsp; ⇒ &nbsp; <b>ω = ω<sub>0</sub> + α t</b>.<br><br><b>(ii) Second Equation (θ = ω<sub>0</sub> t + 1/2 α t<sup>2</sup>):</b><br>By definition ω = dθ / dt ⇒ dθ = ω dt = (ω<sub>0</sub> + α t) dt.<br>Integrating: ∫<sub>0</sub><sup>θ</sup> dθ = ∫<sub>0</sub><sup>t</sup> (ω<sub>0</sub> + α t) dt ⇒ <b>θ = ω<sub>0</sub> t + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> α t<sup>2</sup></b>.<br><br><b>(iii) Third Equation (ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ):</b><br>α = dω / dt = (dω / dθ) (dθ / dt) = ω (dω / dθ) ⇒ ω dω = α dθ.<br>Integrating: ∫<sub>ω0</sub><sup>ω</sup> ω dω = α ∫<sub>0</sub><sup>θ</sup> dθ ⇒ [ ω<sup>2</sup> / 2 ]<sub>ω0</sub><sup>ω</sup> = α θ ⇒ <b>ω<sup>2</sup> - ω<sub>0</sub><sup>2</sup> = 2 α θ</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q89: Complete Theory & Applications of Conservation of Angular Momentum</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">State the Law of Conservation of Angular Momentum. Explain in detail 3 physical applications: (i) Ice skater spinning, (ii) Diver springboard somersaults, (iii) Planetary orbital speed variation.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Statement:</b> In an isolated system (τ<sub>ext</sub> = 0), total angular momentum L = I ω remains constant.<br><br><b>(i) Ice Skater / Ballet Dancer:</b><br>When skater extends arms, mass is far from axis, so I<sub>1</sub> is large and ω<sub>1</sub> is small. When arms are pulled close to chest, mass distribution contracts, reducing moment of inertia to I<sub>2</sub> < I<sub>1</sub>. To keep L = I<sub>1</sub> ω<sub>1</sub> = I<sub>2</sub> ω<sub>2</sub> constant, spin speed ω<sub>2</sub> increases dramatically.<br><br><b>(ii) Diver Somersaults:</b><br>Diver leaves springboard with initial angular momentum. In air, diver tucks knees and arms tight (curling into a ball) to minimize I, maximizing angular velocity ω for multiple fast somersaults. Before entering water, diver extends limbs to increase I and slow down rotation for clean vertical entry.<br><br><b>(iii) Planetary Orbits (Kepler's 2nd Law):</b><br>Sun exerts gravitational force along radius vector (torqueless: τ = r × F = 0). Thus angular momentum L = m r v sin φ is conserved. At perihelion (closest distance r<sub>1</sub>), velocity v<sub>1</sub> is maximum. At aphelion (farthest distance r<sub>2</sub>), velocity v<sub>2</sub> is minimum.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q90: Derivation of Rotational Kinetic Energy & Torque-Inertia Relation</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive expressions for (i) Rotational Kinetic Energy E<sub>rot</sub> = 1/2 I ω<sup>2</sup>, and (ii) Torque τ = I α for a rigid body rotating about a fixed axis.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Consider a rigid body consisting of particles of masses m<sub>1</sub>, m<sub>2</sub>, ... at perpendicular distances r<sub>1</sub>, r<sub>2</sub>, ... from rotation axis. All particles rotate with same angular velocity ω and angular acceleration α.<br><br><b>(i) Rotational Kinetic Energy:</b><br>Linear speed of i-th particle: v<sub>i</sub> = r<sub>i</sub> ω.<br>Total K.E. = ∑ 1/2 m<sub>i</sub> v<sub>i</sub><sup>2</sup> = ∑ 1/2 m<sub>i</sub> (r<sub>i</sub> ω)<sup>2</sup> = 1/2 ( ∑ m<sub>i</sub> r<sub>i</sub><sup>2</sup> ) ω<sup>2</sup>.<br>Since I = ∑ m<sub>i</sub> r<sub>i</sub><sup>2</sup>: <b>E<sub>rot</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> I ω<sup>2</sup></b>.<br><br><b>(ii) Torque Relation τ = I α:</b><br>Linear force on i-th particle: F<sub>i</sub> = m<sub>i</sub> a<sub>i</sub> = m<sub>i</sub> (r<sub>i</sub> α).<br>Torque on i-th particle: τ<sub>i</sub> = r<sub>i</sub> F<sub>i</sub> = m<sub>i</sub> r<sub>i</sub><sup>2</sup> α.<br>Total Torque τ = ∑ τ<sub>i</sub> = ( ∑ m<sub>i</sub> r<sub>i</sub><sup>2</sup> ) α = <b>I α</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q91: Complete Mechanical Equilibrium of Rigid Bodies & Conditions</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Explain complete mechanical equilibrium of a rigid body. State 6 scalar equilibrium conditions and discuss the difference between center of mass and center of gravity.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Mechanical Equilibrium:</b> A rigid body is in complete equilibrium if it has neither translational acceleration nor rotational acceleration.<br><br><b>6 Scalar Conditions:</b><br>1. ∑ F<sub>x</sub> = 0 (No x-translation)<br>2. ∑ F<sub>y</sub> = 0 (No y-translation)<br>3. ∑ F<sub>z</sub> = 0 (No z-translation)<br>4. ∑ τ<sub>x</sub> = 0 (No x-axis rotation)<br>5. ∑ τ<sub>y</sub> = 0 (No y-axis rotation)<br>6. ∑ τ<sub>z</sub> = 0 (No z-axis rotation)<br><br><b>Difference: CM vs Center of Gravity (CG):</b><br>- <b>Centre of Mass (CM):</b> Point where total mass of body is concentrated (independent of gravitational field).<br>- <b>Center of Gravity (CG):</b> Point where net gravitational force (weight) acts.<br>- CM and CG coincide in uniform gravitational fields, but differ in large celestial bodies across non-uniform gravity fields!\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q92: Derivation of Rolling Motion Total K.E. & Acceleration on Inclined Plane</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Derive total kinetic energy of a body rolling without slipping. Derive expression for acceleration a = g sin θ / (1 + k<sup>2</sup>/R<sup>2</sup>) down an incline of angle θ.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>Total K.E. of Rolling Body:</b><br>E<sub>total</sub> = E<sub>trans</sub> + E<sub>rot</sub> = 1/2 M v<sup>2</sup> + 1/2 I ω<sup>2</sup>.<br>Substitute I = M k<sup>2</sup> and ω = v/R:<br><b>E<sub>total</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">2</span>\n  </span> M v<sup>2</sup> [ 1 + <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">k<sup>2</sup></span>\n    <span style=\"padding: 0 2px; display: inline-block;\">R<sup>2</sup></span>\n  </span> ]</b>.<br><br><b>Acceleration down Inclined Plane:</b><br>Forces on incline: Downward gravity M g sin θ, Static friction f up incline.<br>1. Linear motion: M g sin θ - f = M a.<br>2. Rotational motion: Torque τ = f R = I α = (M k<sup>2</sup>) (a / R) ⇒ f = M a (k<sup>2</sup> / R<sup>2</sup>).<br>Substitute f into linear equation:<br>M g sin θ - M a (k<sup>2</sup> / R<sup>2</sup>) = M a ⇒ M g sin θ = M a [ 1 + (k<sup>2</sup> / R<sup>2</sup>) ].<br><b>Acceleration a = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">g sin θ</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">1 + k<sup>2</sup>/R<sup>2</sup></span>\n  </span></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q93: Detailed Moments of Inertia Comparison of Standard Bodies</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">List and compare moments of inertia of Ring, Disc, Solid Sphere, Hollow Sphere, and Rod. Determine which body reaches bottom of an inclined plane first when rolling together.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      <b>MI Formulas & k<sup>2</sup>/R<sup>2</sup> Values:</b><br>1. Thin Ring (CM): I = M R<sup>2</sup> ⇒ k<sup>2</sup>/R<sup>2</sup> = <b>1.00</b><br>2. Hollow Sphere: I = 2/3 M R<sup>2</sup> ⇒ k<sup>2</sup>/R<sup>2</sup> = <b>0.67</b><br>3. Uniform Disc: I = 1/2 M R<sup>2</sup> ⇒ k<sup>2</sup>/R<sup>2</sup> = <b>0.50</b><br>4. Solid Sphere: I = 2/5 M R<sup>2</sup> ⇒ k<sup>2</sup>/R<sup>2</sup> = <b>0.40</b><br><br><b>Race down Incline Analysis:</b><br>Acceleration a = g sin θ / (1 + k<sup>2</sup>/R<sup>2</sup>).<br>The body with the SMALLEST k<sup>2</sup>/R<sup>2</sup> has the LARGEST acceleration and reaches bottom FIRST!<br>Order of arrival: <b>1st Solid Sphere (a = 5/7 g sin θ) → 2nd Disc (a = 2/3 g sin θ) → 3rd Hollow Sphere (a = 3/5 g sin θ) → 4th Ring (a = 1/2 g sin θ)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q94: CM of 4 Particles Square System Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Four masses 1 kg, 2 kg, 3 kg, 4 kg placed at corners of square of side 1 m: (0,0), (1,0), (1,1), (0,1). Find CM coordinates.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Total mass M = 1 + 2 + 3 + 4 = 10 kg.<br><br><b>X<sub>cm</sub>:</b><br>X<sub>cm</sub> = (1×0 + 2×1 + 3×1 + 4×0) / 10 = (0 + 2 + 3 + 0) / 10 = 5 / 10 = <b>0.5 m</b>.<br><br><b>Y<sub>cm</sub>:</b><br>Y<sub>cm</sub> = (1×0 + 2×0 + 3×1 + 4×1) / 10 = (0 + 0 + 3 + 4) / 10 = 7 / 10 = <b>0.7 m</b>.<br><br><b>Centre of Mass position = (0.5 m, 0.7 m)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q95: Rotational Kinematics & Work Master Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A motor of power 2 kW rotates a heavy wheel of I = 10 kg m<sup>2</sup> from rest. Calculate (i) angular acceleration if constant torque of 40 N m is applied, (ii) time to reach 600 rpm, (iii) work done in this time.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Angular acceleration α:</b> α = τ / I = 40 / 10 = <b>4 rad s<sup>-2</sup></b>.<br><br>(ii) <b>Time to reach 600 rpm:</b><br>Target ω = 600 × (2π/60) = 20π ≈ 62.83 rad s<sup>-1</sup>.<br>t = (ω - ω<sub>0</sub>) / α = 20π / 4 = 5π ≈ <b>15.71 seconds</b>.<br><br>(iii) <b>Work Done W:</b><br>By Work-Energy Theorem: W = 1/2 I ω<sup>2</sup> = 1/2 (10) (20π)<sup>2</sup> = 5 × 400 π<sup>2</sup> = 2000 π<sup>2</sup> ≈ <b>19,739 Joules (19.74 kJ)</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q96: Moment of Inertia of Ring & Disc Transverse vs Diameter Proof</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">Prove using perpendicular axis theorem that moment of inertia of a disc about its diameter is 1/4 M R<sup>2</sup>.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Let disc lie in x-y plane. Central transverse axis is z-axis (I<sub>z</sub> = 1/2 M R<sup>2</sup>).<br>By Perpendicular Axis Theorem: I<sub>z</sub> = I<sub>x</sub> + I<sub>y</sub>.<br>By circular symmetry in plane: I<sub>x</sub> = I<sub>y</sub> = I<sub>diameter</sub>.<br>I<sub>z</sub> = 2 I<sub>diameter</sub> ⇒ 1/2 M R<sup>2</sup> = 2 I<sub>diameter</sub>.<br><b>I<sub>diameter</sub> = <span style=\"display: inline-flex; flex-direction: column; vertical-align: middle; text-align: center; font-size: 0.88em; line-height: 1; margin: 0 3px;\">\n    <span style=\"border-bottom: 1.5px solid currentColor; padding: 0 2px; display: inline-block;\">1</span>\n    <span style=\"padding: 0 2px; display: inline-block;\">4</span>\n  </span> M R<sup>2</sup></b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q97: Angular Momentum & Rotational K.E. Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A wheel of I = 0.4 kg m<sup>2</sup> has angular momentum L = 12 kg m<sup>2</sup> s<sup>-1</sup>. Calculate (i) angular velocity, (ii) rotational kinetic energy.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      (i) <b>Angular velocity ω:</b> L = I ω ⇒ ω = L / I = 12 / 0.4 = <b>30 rad s<sup>-1</sup></b>.<br><br>(ii) <b>Rotational K.E.:</b> E<sub>rot</sub> = L<sup>2</sup> / (2 I) = (12<sup>2</sup>) / (2 × 0.4) = 144 / 0.8 = <b>180 Joules</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q98: Diver Springboard Somersault Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A diver in stretched position has I<sub>1</sub> = 15 kg m<sup>2</sup> and rotates at 1 rev s<sup>-1</sup>. When tucked, I<sub>2</sub> drops to 3 kg m<sup>2</sup>. Find (i) new rotational speed, (ii) ratio of final to initial kinetic energy.</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Initial ω<sub>1</sub> = 2π rad s<sup>-1</sup>, I<sub>1</sub> = 15, I<sub>2</sub> = 3.<br><br>(i) <b>New Rotational Speed ω<sub>2</sub>:</b><br>I<sub>1</sub> ω<sub>1</sub> = I<sub>2</sub> ω<sub>2</sub> ⇒ 15 (1 rev/s) = 3 ω<sub>2</sub> ⇒ <b>ω<sub>2</sub> = 5 rev s<sup>-1</sup> (10π rad s<sup>-1</sup>)</b>.<br><br>(ii) <b>K.E. Ratio:</b><br>E<sub>2</sub> / E<sub>1</sub> = (1/2 I<sub>2</sub> ω<sub>2</sub><sup>2</sup>) / (1/2 I<sub>1</sub> ω<sub>1</sub><sup>2</sup>) = (3 × 25) / (15 × 1) = 75 / 15 = <b>5 : 1</b>.<br>(Kinetic energy increases by 5 times due to internal muscular work done by diver while pulling limbs in!).\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q99: Rod Supported by Two Cables Tension Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A 6 kg uniform beam of length 3 m is supported horizontally by cables at ends A and B. A 4 kg mass is hung at 1 m from end A. Find tensions T<sub>A</sub> and T<sub>B</sub> in cables (g = 10 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      Beam weight 60 N acts at center 1.5 m from A. Hung weight 40 N acts at 1 m from A.<br><br><b>1. Vertical Force Equilibrium:</b> T<sub>A</sub> + T<sub>B</sub> = 60 + 40 = 100 N.<br><br><b>2. Rotational Equilibrium (Torque about A):</b><br>T<sub>B</sub> (3) - (60 × 1.5) - (40 × 1.0) = 0.<br>3 T<sub>B</sub> = 90 + 40 = 130 ⇒ <b>T<sub>B</sub> = 130 / 3 ≈ 43.33 Newtons</b>.<br>T<sub>A</sub> = 100 - 43.33 = <b>56.67 Newtons</b>.\n    </div>\n  </div>\n  <div style=\"background: rgba(0,0,0,0.2); border: 1px solid rgba(255,255,255,0.08); border-radius: 10px; padding: 16px; margin-bottom: 20px;\">\n    <h3 style=\"color: #AB47BC; margin: 0 0 10px 0; font-size: 17px; font-weight: bold;\">Q100: Master Rolling Cylinder down Incline Speed Numerical</h3>\n    <div style=\"color: #F0F0F0; margin-bottom: 12px; line-height: 1.6; font-size: 15.5px;\">A solid cylinder of mass 4 kg and radius 0.1 m rolls down an inclined plane of height h = 3 m without slipping. Calculate (i) acceleration down 30° incline, (ii) speed at bottom of incline (g = 9.8 m s<sup>-2</sup>).</div>\n    <div style=\"background: rgba(171, 71, 188, 0.05); border-left: 3.5px solid #AB47BC; padding: 12px 14px; border-radius: 4px; color: #E0E0E0; line-height: 1.6; font-size: 15px;\">\n      <b style=\"color: #AB47BC; display: block; margin-bottom: 6px;\">💡 Solution & Explanation:</b>\n      For solid cylinder k<sup>2</sup>/R<sup>2</sup> = 1/2 = 0.5.<br><br><b>(i) Acceleration down 30° incline:</b><br>a = g sin 30° / (1 + 0.5) = (9.8 × 0.5) / 1.5 = 4.9 / 1.5 = <b>3.27 m s<sup>-2</sup></b>.<br><br><b>(ii) Speed at bottom from height h = 3 m:</b><br>By Energy Conservation: M g h = 1/2 M v<sup>2</sup> (1 + k<sup>2</sup>/R<sup>2</sup>) = 1/2 M v<sup>2</sup> (1.5) = 3/4 M v<sup>2</sup>.<br>v<sup>2</sup> = (4/3) g h = (4/3) × 9.8 × 3 = 4 × 9.8 = 39.2.<br><b>v = √39.2 ≈ 6.26 m s<sup>-1</sup></b>.\n    </div>\n  </div></div>";
